window.UNITS=[{"id":"P1U1","part":1,"n":1,"sec":{"read":{"t":"حَديثُ ضَيْفِ إِبْراهيمَ","pg":5,"paras":[],"voc":[["آيات","مُفرَدُها آيةٌ، وهي العلامةُ."],["الموقِنين","مُفْرَدُها موقن، وَهوَ العالِم المُتأكِّدُ."],["مُنْكَرون","غَيرُ مَعْروفينَ."],["راغَ","رَجَع إِلى أهلهِ."],["أوجَسَ مِنْهُم خيفةً","أحسّ بالخَوْفِ."],["صَرَّة","صَيْحَة."],["صَكَّتْ","لَطَمَتْ."],["عَقيمٌ","لم تلدْ قَطّ."],["خَطْبُكُم","شأنُكُم."],["مُسوَّمَة","مُعلَّمَة."]],"img":[["p1-5.webp",5],["p1-6.webp",6],["p1-7.webp",7]]},"poem":{"t":"أهْلًا بالضَّيْفِ","pg":8,"verses":[["إِذا المَرْءُ وافى مَنْزِلاً مِنْكَ قاصِداً","قِراكَ، وَأرْمَتْهُ لَدَيكَ المَسالِكُ"],["فَكُنْ باسِماً في وَجْهِهِ مُتَهلّلاً","وَقُلْ مَرْحَباً أهْلاً وَيَومٌ مُبارَكُ"],["وقَدّمْ لَهُ ما تَسْتَطيعُ مِنَ القِرى","عَجولاً، وَلا تَبْخلْ بِمَا هُوَ هَالِكُ"],["فَقدْ قيلَ بَيتٌ سالِفٌ مُتقدِّمٌ","تَداوَلَهُ زَيْدٌ وَعَمْرٌو وَمالكُ"],["بَشاشَةُ وَجهِ المَرْءِ خَيرٌ مِنَ القِرى","فَكَيْفَ بِمَنْ يأتِي بِهِ وَهْوَ ضاحِكُ"]],"voc":[["﴿﴾ (الذاريات","١٩)"],["﴿﴾ (الذاريات","٢٣)"],["قاصِداً","طالِباًُ."],["قِراكَ","طعامُ ضَيْفِكَ."],["أرْمَتْهُ","سَاقَتْه"],["مُتهلِّلاً","فَرِحاً."],["تَداوَلَهُ","تَناقَلَه."]],"img":[["p1-8.webp",8],["p1-9.webp",9]]},"grammar":{"t":"مِنْ عَلاماتِ الاسْمِ (مُراجَعَةٌ)","pg":10,"pts":["الاسمُ كلمةٌ تدلُّ على معنًى في نفسِها غيرُ مقترنةٍ بزمن.","من علاماتِ الاسم: قبولُ «ال» التعريف (الضَّيف)، والتنوين (ضيفٌ)، ودخولُ حرفِ الجرّ عليه (إلى البيتِ)، والنداء (يا إبراهيمُ)."],"img":[["p1-10.webp",10],["p1-11.webp",11]],"q":[["أيُّ الكلماتِ الآتيةِ اسمٌ؟",["الضَّيْفُ","أكرمَ","في","قالَ"],0,"قَبِلَ «ال» التعريف."],["ما علامةُ الاسميّةِ في كلمة «بِعِجْلٍ»؟",["دخولُ حرفِ الجرّ والتنوين","قبولُ «ال»","النداء","لا علامة"],0,"سُبقت بحرف الجرّ ونُوِّنت."],["أيُّ الكلماتِ لا تقبلُ علاماتِ الاسم؟",["سَلَّمَ","قومٌ","الآياتِ","غلامٍ"],0,"«سَلَّمَ» فعلٌ ماضٍ."]]},"imla":{"t":"هَمْزَةُ الوَصْلِ وَهَمْزَةُ القَطْعِ","pg":12,"pts":["همزةُ القطعِ تُكتب وتُلفظ في أوّل الكلام ووسطه، وتُرسم على الألف (أ، إ).","همزةُ الوصلِ تُلفظ في أوّل الكلام وتسقط في وصله، وتُكتب ألفًا بلا همزة (ا)."],"img":[["p1-12.webp",12]]},"khatt":{"t":"حرفا (ف، ك)","pg":15,"pts":["حرفا (ف، ك) بخطّ النَّسخ."],"img":[["p1-15.webp",15]]},"taabir":{"t":"إِكْمالُ فَراغٍ","pg":15,"pts":["إكمالُ الفراغ بكلماتٍ مناسبةٍ للسّياق."],"img":[["p1-15.webp",15]]}},"listen":"أكْرَمُ مِنْ حاتِمٍ"},{"id":"P1U2","part":1,"n":2,"sec":{"read":{"t":"شارِعٌ في غَزَّةَ","pg":17,"paras":["في حيِّ الشّجاعيَّةِ بِغزَّةَ، وَفي تِلْكَ الأيَّامِ منْ سنةِ 1936م، ما أكثرَ ما كانَ يُشاهَدُ على الطَّريقِ الفلّاحاتُ الغَزِّيّاتُ، وهنَّ يُقدِّمنَ أرْغِفَةَ الخُبْزِ، وَأقْراصَ الجُبْنِ إِلى أولئكَ الَّذينَ جاؤوا مِنَ المُدُنِ والقُرى اللّيبيَّةِ حامِلينَ أرْواحَهُم عَلى أكفِّهِم؛ لِمُؤازَرَةِ إِخْوانِهِم في فِلَسْطينَ!","وَما أكْثَرَ ما كانَ يُشاهِدُ عابِرُ السَّبيلِ أيْضاً، حَفاوَةَ اسْتِقبالِ الفلّاحِ الغَزِّيِّ لِأخيهِ اللّيبيِّ الَّذي قَطَعَ ثَلاثةَ آلافِ كيلو مترٍ سَيْراً عَلى قَدميْهِ، مِنْ أجْلِ الوُقوفِ مَعَ إِخْوانِهِ الفِلَسطينيّينَ!","وَلَيْسَ مِنْ قَبيلِ المُصادَفَةِ أبَداً، أنْ أطْلَقَتِ الجَماهيرُ في مَدينةِ غزَّةَ اسْمَ البَطَلِ عُمَرَ المُخْتارِ على أكْبرِ شَوارِعِها.","ولعلَّ أحَدَ الفلّاحينَ في غزَّةَ راحَ يَرْوي لفلّاحٍ ليبيٍّ مِنَ الجَبَلِ الأخْضَرِ، وهما يجْلِسانِ تحتَ شَجَرةِ الجُمّيزِ في غزَّةَ، قِصَّةَ ذلكَ الشّارعِ الرّئيسِ، الّذي أصْبَحَ يَحْمِلُ اسْمَ هذا البَطَلِ.","فَيَرْتَفِعُ صَوْتُ الفلّاحِ الفِلَسْطينيِّ قائِلاً: عَلى بُعْدِ آلافِ الكيلو مِتْراتِ مِنْ مَدينةِ طَرابُلْسَ اللّيبيّةِ كانتْ هُناكَ مَدينةٌ أخرى عَلى البَحْرِ المُتَوسِّطِ، قديمةٌ قِدَمَ التَّاريخِ، حَكَمَها الرّومانُ كَما حَكَموا طَرابُلْسَ، وَكانَ اسمُ المَدينَةِ غزّةَ، وَتَقْديراً لِلْقَضِيَّةِ الَّتي قاتلَ مِنْ أجْلِها عُمَرُ المُخْتارُ؛ قرَّرَتِ المَدينةُ أنْ تُطْلِقَ اسْمَهُ عَلى أهمِّ شَوارِعِها.","وَتَغْرَوْرِقُ عَيْنا الفلّاحِ الفِلَسْطينيِّ بالدّموعِ، وَهُوَ يُواصِلُ حِكايَتَهُ لِلْفَلّاحِ اللّيبيِّ كَيْفَ احْتجّ المنْدوبُ السّاميُّ البِريطانيُّ عَلى تَخْليدِ الاسمِ في غزَّةَ، وَجاءَتْ ثُلّةٌ مِنَ الجُنودِ البِريطانيّينَ وانْتزَعتِ اللَّوحةَ المُعلَّقَةَ في صَدْرِ الشّارِعِ. وأخرَجَ تِلْميذٌ لَمْ يَتَجاوزِ العاشرَةَ مِنْ عُمْرِهِ (طَبْشورَةً) مِنْ جَيْبِهِ، وكتَبَ اسمَ عُمَرَ المُخْتارِ عَلى حائِطِ الشّارِعِ، وتَبِعَهُ بَعْضُ التّلامِذَةِ، وهاجَتِ الجَماهيرُ المُحتَشِدةُ في الشّارِعِ، وانْدَفَعَ مِنْها مَنِ انْحَنى، وَتَناوَلَ اللَّوحةَ النُّحاسيَّةَ الَّتي تَحْمِلُ اسْمَ عُمَرَ المُختارِ المُلْقاةَ فوْقَ الرَّصيفِ، فَتَناوَلَها ورَفَعَها بِيَديْهِ كالرّايةِ بَينَ الجُموعِ الَّتي انْطَلَقتْ مُجَسِّدةً صورةً بَهيَّةً للتّضامُنِ العَربيِّ، وكانَ ذلكَ بَعْدَ سَنةٍ مِنِ اسْتِشهادِ عُمرَ المُخْتارِ."],"voc":[["مُؤازرَةٌ","مُسانَدَةٌ وَمُساعَدَةٌ."],["حَفاوَة","إِظْهارُ الفَرَحِ والِإكْرام."],["قَبيل المُصادَفَةِ","باب الصُّدْفَةِ."],["الجُمّيز","نَباتٌ يُشْبِهُ التّينِ."],["تَغْرَوْرِق","تَمْتَلِئُ."],["احتجّ","أبْدى مُعارَضَتَهُ."],["ثُلّة","جَماعةٌ من النّاس."],["هاجَتْ","ثارَتْ."],["المُحْتَشِدَة","المُجْتَمِعة."],["مُجَسِّدة","مُوَضِّحة وَمُبْرِزَة."],["بَهيَّة","جَميلَة."]],"img":[["p1-17.webp",17],["p1-18.webp",18],["p1-19.webp",19],["p1-20.webp",20]]},"grammar":{"t":"عَلاماتُ الإِعْرابِ الأصْلِيَّةُ في الأسْماءِ","pg":21,"pts":["العلامةُ الأصليّةُ لرفعِ الاسمِ الضّمّةُ، ولنصبه الفتحةُ، ولجرّه الكسرةُ.","هناك أسماءٌ تُعربُ بعلاماتٍ فرعيّة مثل المثنّى وجمع المذكّر السّالم."],"img":[["p1-21.webp",21],["p1-22.webp",22]],"q":[["ما علامةُ رفعِ «الجَماهيرُ» في: أطلقتِ الجماهيرُ اسمَ البطل؟",["الضّمّة","الفتحة","الكسرة","الألف"],0,"اسمٌ مرفوعٌ بالعلامة الأصليّة."],["«اسمَ» في الجملة السّابقة:",["منصوبٌ وعلامته الفتحة","مرفوعٌ وعلامته الضّمّة","مجرورٌ وعلامته الكسرة","مبنيّ"],0,"مفعولٌ به منصوب."],["ما علامةُ جرِّ «مدينةِ» في: «في مدينةِ غزّةَ»؟",["الكسرة","الضّمّة","الفتحة","الياء"],0,"سُبقت بحرف الجرّ «في»."]]},"imla":{"t":"مِنْ مَواضِعِ هَمْزَةِ الوَصْلِ","pg":23,"pts":["من مواضع همزة الوصل: «ال» التعريف، وأمرُ الفعل الثّلاثيّ (اُكتبْ، اِجلسْ)."],"img":[["p1-23.webp",23]]},"khatt":{"t":"حرفا (خ، د)","pg":24,"pts":["حرفا (خ، د) بخطّ النَّسخ."],"img":[["p1-24.webp",24]]},"taabir":{"t":"اكْتِشافُ كَلِماتٍ خارِجَةٍ عَنِ السِّياقِ","pg":25,"pts":["اكتشافُ كلماتٍ خارجةٍ عن السّياق."],"img":[]}},"listen":"الجَبَلُ الأخْضَرُ"},{"id":"P1U3","part":1,"n":3,"sec":{"read":{"t":"مَدينَةٌ مِنْ بِلادي فِلَسْطينَ (النّاصِرَةُ)","pg":27,"paras":["كَنْعَانِيَّةُ الأصْلِ، فِلَسْطِينِيَّةُ المَنْشَأ، عَرَبِيَّةُ اللُّغَةِ والعاداتِ والتَّقالِيدِ، ذَاتُ نَسِيْجٍ اجْتِمَاعِيٍّ مُتَرابِطٍ، اسْمُها الكَنْعانِيُّ (آبِلْ)، ومَعْناهُ الحَياةُ، إِنَّها مَدِيْنَةُ النَّاصِرَةِ!","تُعَدُّ النَّاصِرَةُ مِنْ أكْبَرِ المُدُنِ الفِلَسْطِيْنِيَّةِ مِساحَةً وأهَمِّيَّةً، وَأجْمَلَها طَقْساً، وَأعْمَقَها تارِيخاً؛ مَا جَعَلَ لَها مَكانةً خَاصَّةً فِي نُفُوسِ الفِلَسْطِينِيّينَ: المُسْلِمينَ، والمَسيحِيِّينَ الَّذِينَ تَرْبِطُهُمْ وَشائِجُ المَحَبَّةِ، والوَحْدَةِ، والتَّوافُقِ.","اسْتَمَدَّتِ النَّاصِرَةُ مَكَانَتَها التَّارِيخِيَّةَ مِنْ كَوْنِها المَدينَةَ الَّتي أقامَ بِها السَّيِّدُ المَسيحُ عيسى، وفيها بُشِّرَتِ السَّيِّدَةُ مَرْيَمُ العَذْراءُ بِميلادِهِ؛ لِذا كانَتْ كَنيسَةُ البِشارةِ مِنْ أهَمِّ مَعالِمِها التّاريخيَّةِ. وَلَها مَكانَةٌ، وَأهَمِّيَّةٌ عِنْدَ المُسْلِمينَ؛ إِذْ يوجَدُ بِها عَددٌ مِنَ المَساجِدِ، مِنْ أشْهرِها الجامِعُ الأبْيَضُ الَّذي شُيِّدَ فِي عَهْدِ والي عَكّا أحْمَدَ بَاشا الْجَزّارِ، وَفيها أضْرِحَةُ الشُّهَداءِ وَالصّالحينَ.","تَقَعُ المَدينَةُ في قَلْبِ الجَليلِ الأدْنَى (الأسْفَلِ)، وَتُلَقَّبُ بِعَروسِ الجَليلِ، وَهِيَ نُقْطَةُ التِقاءِ سَهْلِ مَرْجِ ابْنِ عامِرٍ بِمِنْطَقَةِ الجَليلِ الأعْلى الجَبَلِيَّةِ، تَبْعُدُ عَنْ مَدينَةِ الْقُدْسِ حَوالَي مئةِ كيلو مِتْرٍ، تُحيطُ بِها جِنينُ، - ْوَطَبَرِيّا، وَبيسانُ، وَعَكّا، وَحَيْفا؛ لِذا أصْبَحَتبَعْدَ أحْداثِ النَّكْبَةِ عامَ مَرْكَزاً ثَقافِيّاً وَإِداريّاً لِلْفِلَسْطينِيّينَ.-1948م","يَعْتَمِدُ اقْتِصادُ النّاصِرَةِ عَلى زِراعَةِ الأشْجارِ المُثْمِرَةِ وَالخَضْراواتِ في بُطونِ الأوْدِيَةِ وَالسُّهولِ وَسُفوحِ الجِبالِ المُحيطَةِ بِها، إِضافَةً إِلى الصِّناعات التَّقْليدِيَّةِ، مِثْلِ: الهَدايا التَّذْكارِيَّةِ، وَالدِّباغَةِ والصِّباغَةِ، والحِدادَةِ، وَالخِياطَةِ، وَصِناعَةِ الصّابونِ، وإِنْتاجِ الزَّيْتِ، والطَّحينَةِ.","تَأْتي السِّياحَةُ عَلى رَأْسِ الْعَوامِلِ الَّتي جَعَلَتْ حَرَكَةَ التِّجارَةِ رائِجةً في المَدِينَةِ؛ فَهِيَ مَرْكَزُ جَذْبٍ سِياحِيٍّ مَرْموقٍ، يَسْتَقْبِلُ عَدَداً كَبيراً مِنَ السَّائِحِينَ الّذينَ يَقْصِدونَها لِأغْراضٍ دِينِيَّةٍ وَتَرْفيهِيَّةٍ."],"voc":[["وَشَائِج","مفردها وَشيجَة، وهي الصلة."],["معالمها","آثارها"],["شُيِّدَ","بُنِيَ."],["سُفوح","مفردها سَفْح، وهو أصْلُ الجَبَلِ وَأسْفَلُهُ."],["رائِجَة","مُتَداوَلَة."],["مَرْموق","ذو مَكانَةٍ عاليَةٍ."]],"img":[["p1-27.webp",27],["p1-28.webp",28],["p1-29.webp",29]]},"poem":{"t":"الجَليلُ","pg":30,"verses":[["سَلامٌ عَلى زَيْنِ القُرى والحَواضِرِ","وَمَنْ هاجَروا مِنْها وَمَنْ لَمْ يُهاجِرِ"],["يَمُرُّ بِنا اسْمُ المَرْجِ: مَرْجِ ابْنِ عامِرِ","فَنَطْرَبُ لِاسْمِ المَرْجِ: مَرْجِ ابْنِ عامِرِ"],["ونَحْسَبُهُ أرْضاً بَعيداً مَنالُها","تَضيقُ بِها ذَرْعاً جِمالُ المُسافِرِ"],["وَلَوْ طِفْلَةٌ مِنْ عِنْدِنا مَسَّ شَعْرَها","نَسيمٌ لَمَسَّ المَرْجَ ظِلُّ الضَّفائِرِ"],["وَنَسْمَعُ عَنْ بُعْدٍ فَطوبى لِسامِعٍ","عَلى البُعْدِ مَحْرومٍ وَلَيْسَ بِناظِرِ"],["وَنَنْظُرُ عَنْ بُعْدٍ فَطوبى لِناظِرٍ","عَلى البُعْدِ مَحْرومٍ وَلَيْسَ بِزائِرِ"],["إِذا حاصَرَتْ جِسْمَ الجَليلِ غُزاتُهُ","فَإِنَّ اسْمَهُ قَدْ رَدَّ كَيْدَ المُحاصِرِ"],["فَمَنْ قالَ: بَيْتي في الجَليلِ وَلَمْ يَزِدْ","فَقَدْ قالَ شِعْراً وَهُوَ لَيْسَ بِشاعِرِ"]],"voc":[["الحَواضِرُ","ُجَمْع حاضِرَة، وَهي المُدُنُ."],["نَحْسَبُهُ","نَظُنُّهُ."],["تَضيقُ بِها ذَرْعاً","لم تَتَحَمّلْ مَشاقَّهُ."],["الضَّفائَرُ","جَمْعُ ضَفيرَة، وَهِيَ الجَديلَةُ،."],["طوبى","هَنيئاً."]],"img":[["p1-30.webp",30],["p1-31.webp",31]]},"grammar":{"t":"المُثَنّى","pg":32,"pts":["المثنّى: اسمٌ يدلّ على اثنين أو اثنتين بزيادة ألفٍ ونون أو ياءٍ ونون على مفرده.","يُرفع المثنّى بالألف، ويُنصب ويُجرّ بالياء: جاءَ الطّالبانِ، رأيتُ الطّالبَيْنِ، مررتُ بالطّالبَيْنِ."],"img":[["p1-32.webp",32],["p1-33.webp",33]],"q":[["مثنّى «مدينة» في حالة الرّفع:",["مدينتانِ","مدينتَيْنِ","مدائنُ","مدينات"],0,"يُرفع المثنّى بالألف."],["«زرتُ القريتَيْنِ»: علامةُ نصبِ «القريتين»:",["الياء","الألف","الفتحة","الكسرة"],0,"يُنصب المثنّى بالياء."],["أيُّ الكلماتِ مثنّى؟",["جَبَلانِ","إخوان","بستان","سكّان"],0,"«جبلان» مفرده جبل + ان."]]},"imla":{"t":"إِمْلاءٌ اخْتِبارِيٌّ","pg":34,"pts":["إملاءٌ اختباريٌّ لقطعةٍ من الوحدة."],"img":[["p1-34.webp",34]]},"khatt":{"t":"حرفا (أ، ل)","pg":34,"pts":["حرفا (أ، ل) بخطّ النَّسخ."],"img":[["p1-34.webp",34]]},"taabir":{"t":"كِتابَةُ فِقْرَةٍ","pg":35,"pts":["كتابةُ فِقرةٍ."],"img":[]}},"listen":"عَبْدُ الرَّحيمِ الحاجّ مُحَمَّدٌ"},{"id":"P1U4","part":1,"n":4,"sec":{"read":{"t":"الإِحْسانُ يَصْنَعُ الإِنْسانَ","pg":37,"paras":["انْطَلقتْ تِلْكَ الصَّيحاتُ مِنْ مُسْتنْقعٍ قَريبٍ مِنْ إِحْدى قُرى إسْكُتلَنْدا، فَسَمِعَها فلّاحٌ فَقيرٌ، وَانْطَلَقَ نَحْوَ مَنْطِقَةِ المُسْتنقَعِ؛ مُجيباً ذلكَ الصَّوتَ.","وَهُناكَ كانتِ المفاجَأةُ...! لَقدْ وَجَدَ فتًى يَغوصُ في طينٍ أسْوَدَ كَثيفٍ، وَقَدْ شارَفَ على الهَلاكِ، فَهالَه ما رَآهُ، غَير أنَّهُ تَمكَّنَ بَعْدَ جُهدٍ جَهيدٍ مِنِ انْتِشالِهِ.","في اليَوْمِ التّالي، سَمِعَ الفلّاحُ صَوتَ طَرَقاتٍ على بابِ كوخِهِ، وعِندَما فَتَحَ البابَ وَجَدَ أمامَهُ رَجُلاً تَظْهَرُ عَلَيهِ أماراتُ الثَّراءِ والأناقَةِ، حَيْثُ كانتْ في انْتِظارهِ مَرْكَبَةٌ فَخْمَةٌ أقلَّتْهُ إِلى الكوخِ. تَساءَل الفلّاحُ المِسْكينُ في حَيْرةٍ: ما الَّذي يَجْعَلُ شَخْصَاً مِثْلَ هذا يَأْتي إليّ؟!","كانَ الرَّدُ سَرِيعاً، حَيْثُ بادرَ الرَّجلُ الثَّريُّ قائلِاً: لَقَدْ أنْقَذْتَ ابْني بالأمسِ، وقدَّمْتَ بِذلك نَموذَجاً نَبيلاً في صُنْعِ الخَير، اسْتحقَّ أنْ أكونَ أمامَك؛ لِأقدِّمَ لَكَ مُكافأةً لِقاءَ ذلكَ. هكَذا كانَ ردُّ الرُّجلِ الأنيقِ، لكنَّ الفلَّاحَ رَفَضَ المُكافأةَ الَّتي عُرِضَتْ عَلَيْهِ، وبَيْنما كانَ الرُّجلُ يَجولُ بِنَظَرِهِ في أنْحاءِ المَسْكنِ المُتَواضِعِ، وَقَعَتْ عَيْناه على صَبيٍّ صَغيرٍ كانَ يَقْفِزُ في أرْجاءِ الكوخِ، حينَها قالَ: حَيْثُ إنَّكَ رَفَضْتَ المُكافأةَ، فَهلّا وافقتَ على أنْ أساعِدَ ابنَكَ كما ساعَدْتَ وَلَدي! سَألَهُ الفلّاحُ: وَكَيْفَ يَكونُ ذلكَ؟ أجابَ الرَّجلُ: تَسمحُ لي باصْطحابِ ابنِكَ مَعي، وَسَأحْرِصُ على أنْ يَتَلقّى أرْقى تَعْليمٍ في البِلادِ.افْترَّ فمُ الفلّاحِ الفَقيرِ عَنِ ابْتِسامَةٍ عَريضةٍ، وَقَبِلَ العَرْضَ. التَزَمَ النَّبيلُ الثَّريُّ بِوعْدهِ طيلةَ سَنواتِ دِراسَةِ الصَّبيِّ في المَدارِسِ والجامِعاتِ إِلى أنْ تَخَرَّجَ في كُلِّيةِ الطِّبِّ بِمَدينةِ لَنْدَن.","كانتِ المِنْحَةُ التَّعليميَّةُ الَّتي تلقّاها ابنُ الفلّاحِ مِنَ الرَّجلِ دافِعاً لَهُ؛ لِيقدِّمَ بِدَوْرِهِ هَديَّةً ثَمينةً لِلعالَمِ بِأسْرِه: لَقَدِ اكْتَشَفَ (البَنْسَلين)، وكانَ ذلكَ عام 1928م.","أجَلْ، كانَ الصَّبيُّ هُوَ (ألِكْسَنْدر فليمنج) الَّذي بِفضْلهِ بَدَأتْ صَفحةٌ جَديدَةٌ في عالَمِ الطِّبِّ، حَيْثُ أمْكَنَ عِلاجَ عَديدٍ مِنَ الأوْبِئَةِ والأمْراضِ المُعْدِيَةِ."],"voc":[["شارَف","قارَب."],["هالَه","أفْزَعَهُ."],["أمارات","عَلامات."],["أقلَّته","نَقَلتْه."],["افترَّ","ابتسم، وبدت أسنانه."],["أوْبِئَة","مُفردُها وَباء، وَهُوَ مَرَضٌ سَريعُ العَدْوى."]],"img":[["p1-37.webp",37],["p1-38.webp",38],["p1-39.webp",39],["p1-40.webp",40]]},"poem":{"t":"قُطوفٌ مِنْ شِعْرِ الحِكْمَةِ","pg":41,"verses":[["أخي لَديَّ مِنَ الأيَّامِ تَجْرِبَةٌ","فيما أظنُّ وَعِلمٌ بارِعٌ شافِ"],["لا تَمْشِ في النّاسِ إلّا رَحْمَةً لَهُمُ","وَلا تُعامِلْهُمُ إلّا بإِنْصافِ"],["واقْطَعْ قُوى كُلِّ حِقْدٍ أنْتَ مُضْمِرُهُ","إنْ زَلَّ ذو زَلَّةٍ أوْ إنْ هَفا هافِ"],["وارْغَبْ بِنَفْسِكَ عمّا لا صَلاحَ لَهُ","وَأوْسِعِ النّاسَ مِنْ بِرٍّ وَإِلْطافِ"],["وإنْ يَكُنْ أحَدٌ أوْلاكَ صالِحَةً","فَكافِهِ فَوْقَ ما أوْلى بِأضْعافِ"],["ولا تُكشِّفْ مُسيئاً عن إِساءَتِهِ","وَصِلْ حِبالَ أخيكَ القاطِعِ الجافي"],["فَتَسْتَحقَّ مِنَ الدُّنيا سَلامتَها","وَتَسْتَقِلَّ بِعِرْضٍ وافرٍ وافِ"],["حَسْبُ الفَتى بِتُقى الرَّحمنِ مِنْ شَرَفٍ","وَما عَبيدُكِ يا دُنيا بأشْرافِ"]],"voc":[["هَفا","زَلَّ ومالَ."]],"img":[["p1-41.webp",41],["p1-42.webp",42]]},"grammar":{"t":"الجُموعُ","pg":43,"pts":["الجموع ثلاثة: جمعُ المذكّر السّالم (معلّمون/معلّمين)، وجمعُ المؤنّث السّالم (معلّمات)، وجمعُ التّكسير (كُتُب).","جمعُ المذكّر السّالم يُرفع بالواو ويُنصب ويُجرّ بالياء.","جمعُ المؤنّث السّالم يُرفع بالضّمّة ويُنصب ويُجرّ بالكسرة."],"img":[["p1-43.webp",43],["p1-44.webp",44]],"q":[["نوعُ الجمعِ في «المُحسِنون»:",["جمعُ مذكّرٍ سالم","جمعُ مؤنّثٍ سالم","جمعُ تكسير","مثنّى"],0,"سَلِم مفرده وزيدت واو ونون."],["نوعُ الجمعِ في «أشجار»:",["جمعُ تكسير","جمعُ مذكّرٍ سالم","جمعُ مؤنّثٍ سالم","مثنّى"],0,"تغيّرت صورة المفرد «شجرة»."],["«شاهدتُ المعلّماتِ»: علامةُ نصبِ «المعلّمات»:",["الكسرة","الفتحة","الياء","الألف"],0,"جمع المؤنّث السّالم يُنصب بالكسرة."]]},"imla":{"t":"مِنْ مَواضِعِ هَمْزَةِ القَطْعِ","pg":46,"pts":["من مواضع همزة القطع: الأفعالُ الرّباعيّة ماضيًا وأمرًا ومصدرًا (أكرمَ، أكرِمْ، إكرام)، وهمزةُ المضارعة (أكتبُ)، والأسماء عدا العشرة المسموعة (أحمد، أمّ)."],"img":[["p1-46.webp",46]]},"khatt":{"t":"حرفا (ب، س)","pg":48,"pts":["حرفا (ب، س) بخطّ النَّسخ."],"img":[["p1-48.webp",48]]},"taabir":{"t":"كِتابَةُ قِصَّةٍ","pg":49,"pts":["كتابةُ قصّة."],"img":[]}},"listen":"في الصَّحْراءِ"},{"id":"P1U5","part":1,"n":5,"sec":{"read":{"t":"التَّلَوُّثُ الصَّوْتِيُّ","pg":51,"paras":["اعْتَلَى عَمْرٌو مِنَصَّةَ الإِذاعَةِ المَدْرَسِيَّةِ مُمَثَّلاً عَنِ النّادِي البيئِيِّ في المَدْرَسَةِ؛ لِيُلْقِيَ كَلِمَتَهُ، فَأمْسَكَ بِالمِجْهارِ (المَيْكروفون) بِثِقَةٍ، وَقَد ارْتَسَمَتِ ابْتِسامَةٌ عَلى مُحَيّاهُ، وَانْطَلَقَ صَوْتُهُ قائِلاً: لَقَد شَهِدَ عالَمُنا فِي القَرْنِ المُنْصَرِمِ تَقَدُّماً صِناعِيّاً، وَتَطَوُّراً حَضارِيّاً مُذْهِلاً، وَمَعَ هذا التَّقَدُّمِ ظَهَرَ التَّلَوُّثُ البيئِيُّ بِصُوَرِهِ، وَأشْكالِهِ المُتَعَدِّدَةِ: كَالتَّلَوُّثِ المائِيِّ، وَالتَّلَوُّثِ الهَوائِيِّ، وَتَلَوُّثِ التُّرْبَةِ، وَالتَّلَوُّثِ الصَّوْتِيِّ.","وَيُعَرَّفُ التَّلوُّثُ الصَّوتيُّ بِأنَّهُ كُلُّ صَوْتٍ غَيْرِ مَرْغوبٍ فِيهِ؛ لِزِيادَةِ حِدَّتِهِ وَشِدَّتِهِ، وَخُروجِهِ عَنِ المَأْلوفِ، وَعَنِ الأصْواتِ الطَّبيعِيَّةِ الَّتي اعْتادَ الإِنْسانُ سَماعَها، وَيُقاسُ بِمَقاييسَ مُتَعَدِّدَةٍ مِنْ أشْهَرِها (الدّيسِبْل) الَّذي يُعَرَّفُ بِأنَّهُ الوِحْدَةُ المُسْتَخْدَمَةُ لِقِياسِ شِدَّةِ الصَّوْتِ.","تَزْدادُ مُشْكِلَةُ التَّلَوُّثِ الصَّوْتِيِّ يَوْماً بَعْدَ يَوْمٍ بِازْدِيادِ مَصادِرِهِ، وَمِنْها المُنْشَآتُ الصِّناعِيَّةُ، وَالآلاتُ الثَّقيلَةُ، وَمُكَبِّراتُ الصَّوْتِ، وَوَسائِلُ النَّقْلِ، كَالمَرْكَباتِ، وَالحافِلاتِ، وَالطّائِراتِ، وَالقِطاراتِ؛ لِما تُصْدِرُهُ مِنْ أصْواتٍ وَموسيقا صاخِبَةٍ تَصُكُّ الآذانَ، إِضافَةً إِلى أصْواتِ المَدافِعِ وَالصَّواريخِ في الحُروبِ الَّتي تُثيرُ الهَلَعَ وَالفَزَعَ بَيْنَ النّاسِ.","لِلتَّلَوُّثِ الصَّوْتِيِّ آثارٌ سَلْبِيَّةٌ، وَأضْرارٌ مُتَعَدِّدَةٌ، فقدْ يُؤَدّي التَّعَرُّضُ لَهُ بِاسْتِمْرارٍ إِلى الإِصابَةِ بِأمْراضٍ مِنْ أبْرَزِها فُقْدانُ السَّمْعِ الجُزْئِيِّ وَالكُلِّيِّ المُؤَقَّتِ وَالدّائِمِ، وَكَذلِكَ ارْتِفاعُ ضَغْطِ الدَّمِ، وَزِيادَةُ نِسْبَةِ السُّكَّرِ فيهِ، وَالتَّأثيرُ عَلى النَّومِ، وَإِحْداثُ تَهَيُّجٍ في الجِهازِ العَصَبِيِّ؛ ما يُسَبِّبُ الشُّعورَ بِالقَلَقِ وَالتَّوَتُّرِ...","وَلِلتَّخْفيفِ مِنْ آثارِ هَذهِ الظَّاهِرَةِ؛ لا بُدَّ مِنْ نَشْرِ الوَعْيِ بمَخاطِرِها، والحَدِّ مِنْها، وَتَجَنُّبِ اسْتِخْدامِ الأصْواتِ المُزْعِجَةِ كَأبْواقِ السَّيّاراتِ الَّتي تُفْسِدُ الهُدوءَ، وَتُعَكِّرُ الصَّفْوَ، وَتَقومُ الحُكوماتُ بِإِنْشاءِ المُدُنِ الصِّناعِيَّةِ، وَالمَطاراتِ، وَطُرُقِ وَسائِلِ المُواصَلاتِ الثَّقيلَةِ بَعيداً عَنِ المَناطِقِ السَّكَنِيَّةِ.","إِنَّ الحَدَّ مِنْ ظاهِرَةِ التَّلَوُّثِ الصَّوْتِيّ أمْرٌ في غايَةِ الأهَمِّيَّةِ، إِذْ يُساعِدُ عَلى التَّرْكيزِ، وَيَبْعَثُ راحَةً في النَّفْسِ، وَيَعْكِسُ صورَةً إِيجابِيَّةً عَنِ السُّلوكِ المُجْتَمَعيِّ."],"voc":[["مُحَيّاهُ","وَجْهُهُ."],["مُذْهِلاً","مُدْهِشاً."],["تَصُكُّ الآذانَ","تُؤْذيها."]],"img":[["p1-51.webp",51],["p1-52.webp",52],["p1-53.webp",53],["p1-54.webp",54]]},"grammar":{"t":"عَلاماتُ إِعْرابِ الفِعْلِ المُضارِعِ الأصْلِيَّةُ","pg":55,"pts":["يُرفع الفعلُ المضارعُ بالضّمّة إذا لم يُسبق بناصبٍ ولا جازم (يكتبُ).","يُنصب بالفتحة إذا سُبق بناصب (لن يكتبَ).","يُجزم بالسّكون إذا سُبق بجازم (لم يكتبْ)."],"img":[["p1-55.webp",55],["p1-56.webp",56]],"q":[["«لَنْ يَنْجَحَ المُهمِلُ»: علامةُ نصب «يَنْجَحَ»:",["الفتحة","الضّمّة","السّكون","الكسرة"],0,"سُبق بالنّاصب «لن»."],["«لم يَحْضُرْ»: الفعلُ «يحضرْ»:",["مجزومٌ وعلامته السّكون","منصوبٌ وعلامته الفتحة","مرفوعٌ وعلامته الضّمّة","مبنيّ"],0,"سُبق بالجازم «لم»."],["«يُحافِظُ النّاسُ على الهدوء»: «يحافظ» مرفوعٌ لأنّه:",["لم يُسبق بناصبٍ أو جازم","سُبق بناصب","سُبق بجازم","فعل أمر"],0,""]]},"imla":{"t":"هَمْزَةُ (ابْن، وابْنَة)","pg":57,"pts":["همزةُ «ابن» و«ابنة» همزةُ وصل.","تُحذف ألفُ «ابن» إذا وقعت مفردةً بين عَلَمين ثانيهما أبٌ للأوّل ولم تقع في أوّل السّطر (محمّدُ بنُ عبدِ الله)."],"img":[["p1-57.webp",57]]},"khatt":{"t":"حرف (ع)","pg":60,"pts":["حرف (ع) بخطّ النَّسخ."],"img":[["p1-60.webp",60]]},"taabir":{"t":"كِتابَةُ لافِتاتٍ","pg":61,"pts":["كتابةُ لافتات."],"img":[]}},"listen":"تَرْشيدُ اسْتِهْلاكِ المِياهِ"},{"id":"P1U6","part":1,"n":6,"sec":{"read":{"t":"سَنابِلُ الحِكْمَةِ","pg":63,"paras":["مُنْذُ آلافِ السِّنينَ والبَشَريَّةُ تَحْظَى بالمُفكِّرينَ وَالنَّوابِغِ الَّذينَ نَقَشوا حِكْمَتَهُمْ عَلى الحَجَرِ، أو خَطُّوها عَلى جُلودِ الحَيَوانَاتِ، أو كَتَبوها عَلى وَرَقِ البَرديِّ، أو نَضَّدوها عَلى الآلةِ الكاتِبَةِ، وَمُنْذُ آلافِ السِّنينَ وَقفَ هؤُلاءِ فَوْقَ المَنابِرِ يَعِظونَ، وَجَلَسوا إِزاءَ السَّلاطِينِ وَالمُلوكِ والأمراءِ يَنْصَحونَ، وَسَاروا في أرْوِقَةِ الأدْيِرَةِ والقُصورِ يُلْقونَ العِظاتِ والوَصايا، وَجَلَسوا تَحْتَ قِبابِ المَساجِدِ يَأمُرون بالمَعْروفِ، وَيَنْهَونَ عَنِ المُنْكَرِ.","إنَّ ما خَالَجَ هَؤُلاءِ الحُكَماءَ قَديماً هوَ نَفْسُهُ ما يُخالِجُ حُكَماءَ اليَوْمِ؛ فالمَوْضُوعاتُ الَّتي عُرِضَتْ لِلْإ نسانِ قَديماً هِيَ نَفْسُهَا الَّتي تُعْرَضُ لَهُ اليَوْمَ، وَالتَّجارِبُ التي مَرَّ بِها أجْدَادُنا هي نَفْسُها التَّجارِبُ الَّتي نَمُرُّ بِها حَاليّاً، لَكِنَّ الفارِقَ بَيْنَنَا وَبَيْنَهُم أنَّنا تَمَكَّنّا مِنَ الاطِّلاعِ عَلى تِلْكَ الحِكَمِ والخَواطِرِ مُدوَّنَةً، بَيْنَما لمْ يَسْتَطِعِ الأوَّلُونَ مَعْرِفَةَ ما قَالَهُ سابِقوهُم.","إنَّ الكُتُبَ الَّتي تَضُمُّ في بُطُونِها هذهِ الحِكَمَ أشْبَهُ ما تَكُونُ بالبَحْرِ الَذي يَخْتَزِنُ في أعْماقِهِ أنْقى اللآلِئِ وَألمَعَها، والغوّاصُ الماهِرُ هو ذلكَ الَّذي يَغوصُ باحِثاً عنْها، مُتلمِّساً بَريقَها، مُتَذَوِّقاً بلاغَتَها، مُسْتَلْهِماً ما فيها مِنْ خِبْرَةٍ وَتَجْرِبةٍ غَنيَّةٍ.","والحِكَمُ لَيْستْ حِكْراً عَلى شَعْبٍ دونَ آخَرَ، وَلا عَلى أمَّةٍ دونَ أخْرى، بَلْ هي عُصارَةُ التَّجارِبِ الإ نسانيَّةِ الحَياتيَّةِ المُشْتركَةِ، نَتَعَرَّفُ مِنْ خِلالِها عَاداتِ الأمَمِ والشُّعُوبِ وَتَقاليدَها وَمَعَاييرَها الأخْلاقيَّةَ، وَرَغْمَ أنَّ لِكلِّ أمَّةٍ وَكلِّ شَعبٍ خُصوصِيّةً وَسِمَةً حَضارِيَّةً، وَأنَّ مِضْمارَ السِّباقِ في الإِبْداعِ بَيْنَ الأمَمِ لا حدَّ لَهُ، إلّا أنَّ الحِكَمَ تَظَلُّ تُراثاً إِنْسانيّاً مُشْتَرَكاً مُتَوارَثاً بَيْنَ الأجْيالِ، يَصْلُحُ لِكلِّ إنسانٍ في كُلِّ زَمانٍ وَمَكانٍ.","إنَّها قَناديلُ تُنِيرُ للتّائِهينَ طَريقَهُم، وَسَنابِلُ تَسْتَعْصي على الفَناءِ، وأشجارٌ باسِقةٌ تَعِزُّ عَلى الاجْتِثَاثِ، يَفِيءُ إلِى ظِلِّهِا المَكْدودونَ مِنْ كُلِّ حَدَبٍ وَصَوْبٍ، يَنْشُدونَ الرّاحَةَ.","إِنَّ في الحِكْمَةِ عِظَةً وَعِبْرَةً، وَدافِعاً يَدْفَعُ قارِئَها أو سامِعَها إِلى الإِقْبالِ عَلى الفَضيلةِ، وَيَبْتَعدُ بِهِ عَنِ الرَّذيلَةِ، وَلِذا نَرى الحِكَمَ مُعلَّقةً عَلى جُدْرانِ الكَثيرِ مِنَ المَنازِلِ، والمَحالِّ التِّجاريَّةِ أو المُؤَسساتِ، وَغَيْرِها مِنَ المَرافِقِ العامَّةِ. وَإلَيكَ طائفةً مِنَ الحِكَمِ:"],"voc":[["(البقرة","٢٦٩)"],["البَردي","نَباتٌ اسْتَخْدَمَ القُدَماءُ أوْراقَهُ في الكِتابَةِ."],["نَضَّدوها","نَسَّقوهَا."],["أرْوِقة","مُفْرَدُها رِواق، وهو رُكنٌ في مَسْجدٍ أوْ مَعْبدٍ أو منزل قديم."],["خالَجَ","خالَطَ."],["اجْتِثاث","اقْتِلاع."],["مَكدود","مُتْعَب."],["حَدَبٍ وَصَوْب","من الجِهاتِ كلِّها."]],"img":[["p1-63.webp",63],["p1-64.webp",64],["p1-65.webp",65],["p1-66.webp",66]]},"poem":{"t":"رُؤْيا","pg":67,"verses":[["إِنّي رَأيْتُ جَرادةً مَطْروحَةً","في سَبْخَةٍ مَنْهوكةَ الأعْضاءِ"],["تَرْنو إِلى الأفُقِ البَعيدِ بِمُقْلَةٍ","كَلْمى، وَتَشْتُمُ أنْجُمَ الجَوْزاءِ"],["فَسَألتُها: ماذا عَراكِ؟ فَلَمْ تُجِبْ","فَسَألتُ عَنْها زُمْرةَ الرُّفَقاءِ"],["قَالوا: رَفِيقَتُنا شَهيدةُ هُزْئِها","بِنَصائِحِ العُقَلاءِ والحُكَماءِ"],["كانَتْ إِذا جاعَتْ فَحبَّةُ خَرْدَلٍ","تَكْفي، وإنْ عَطِشَتْ فَنُقْطَةُ ماءِ"],["سَمِعَتْ بِنَهْرٍ في السَّماءِ وَجنَّةٍ","لَيستْ لِتَصْويحٍ ولا لِفَناءِ"],["العِطْرُ في أثْمارِها، والشَّهْدُ في","أنْهارِها، والسِّحرُ في الأنْداءِ"],["فَمَضَتْ تُحلِّقُ في الفَضاءِ وَلمْ تَزَلْ","حَتّى وَهَتْ فَهَوَتْ إِلى الغبْراءِ"],["هذي حِكايتُها وَفيها عِبْرَةٌ","للطّائِشينَ كَهذهِ الحَمْقاءِ"]],"voc":[["خَرْدَل","نَباتٌ عُشْبِيٌ، بَذْرَتُهُ صَغيرَةُ الحَجْمِ، يَنْبُتُ بَيْنَ الزَّرْعِ."]],"img":[["p1-67.webp",67]]},"grammar":{"t":"الفِعْلُ المُجَرَّدُ وَالفِعْلُ المَزيدُ","pg":68,"pts":["الفعلُ المجرّد: ما كانت حروفُ ماضيه كلُّها أصليّة (كَتَبَ، دَحْرَجَ).","الفعلُ المزيد: ما زِيد على حروفه الأصليّة حرفٌ أو أكثر (أكْرَمَ، تَعَلَّمَ، اسْتَغْفَرَ).","نعرف الحروف الأصليّة بالرّجوع إلى الماضي المسند إلى المفرد الغائب."],"img":[["p1-68.webp",68],["p1-69.webp",69]],"q":[["الفعل «اسْتَخْرَجَ»:",["مزيدٌ بثلاثة أحرف","مجرّدٌ ثلاثيّ","مزيدٌ بحرف","مجرّدٌ رباعيّ"],0,"أصله «خَرَجَ»."],["أيُّ الأفعالِ مجرّد؟",["جَلَسَ","أجْلَسَ","تَجالَسَ","جالَسَ"],0,""],["الفعل «عَلَّمَ» مزيدٌ بـ:",["تضعيف العين","همزة","ألف","تاء"],0,"أصله «عَلِمَ»."]]},"imla":{"t":"إِمْلاءٌ اخْتِبارِيٌّ","pg":70,"pts":["إملاءٌ اختباريّ."],"img":[["p1-70.webp",70]]},"khatt":{"t":"حرفا (ر، هـ)","pg":71,"pts":["حرفا (ر، هـ) بخطّ الرُّقعة والنّسخ."],"img":[["p1-71.webp",71]]},"taabir":{"t":"نَثْرُ قَصيدَةٍ","pg":71,"pts":["نثرُ قصيدة."],"img":[["p1-71.webp",71]]}},"listen":"المَأمونُ وَمُؤَدِّبُ وَلَدَيْهِ"},{"id":"P1U7","part":1,"n":7,"sec":{"read":{"t":"حُبُّ الوَطَنِ","pg":73,"paras":["الوَطَنُ أثْمنُ ما في حَياةِ الإ نْسانِ، لا يَعْلو عَليهِ عالٍ، ولا يَغْلو أمامَهُ غالٍ، فَالإِنْسانُ يَسْتَمِدُّ مِنْهُ انْتِماءَهُ، وَيُحقِّقُ بِهِ وُجودَهُ؛ وَلِذا يَبْذُلُ الغالِيَ والنَّفيسَ في سَبيلِهِ، فَيُقَدِّمُ حَياتَهُ ثَمناً لِحُرِّيَّتِهِ؛ دِفاعاً عَنْ تُرابِهِ.","والوَطنُ لَيْسَ بُقْعَةً جُغرافِيَّةً فَحَسْبُ، بلْ هوَ مَجْموعَةٌ مِنَ المُكَوِّناتِ الَّتي تَتَشابَكُ وتَتفاعلُ بَعْضِها معَ بَعْضٍ، فَتُعْطي لِهذهِ البُقْعةِ مَعناها السّامِيَ، وَقِيمَتَها الخالِدَةَ، أجَلْ، لَقَدْ شَهِدَتْ هذهِ البُقْعَةُ خُطواتِنا المُتَعثِّرَةَ صِغاراً، وَاخْتَزَنتْ ذِكْرَياتِنا كِباراً، وَارْتَسَمتْ صُوَرُ غُيومِها، وَنُجومِها، وَسُهولِها، وَجِبالِها، وَطُيورِها، وَأشْجارِها في سُوَيداءِ قُلوبِنا، تُبارِكُ حُبَّنا لَها، وَتَعلُّقَنا بِها. كَما تَنَفَّسْنا هَواءَها، وَتَدثَّرْنا بِسَمائِها، وَذُقْنا حَلاوَةَ الطُّمأْنينَةِ في حِماها.","تَغنّى الشُّعراءُ والأدَباءُ وَغَيْرُهم بِأوْطانِهم مُنْذُ أقْدمِ العُصورِ، فَالعَربِيُّ الجاهِلِيُّ الَّذي كانَ يَتنقَّلُ مِنْ مَكانٍ إِلى آخرَ؛ بَحثاً عن الكلَأِ والماءِكانَ يَشعرُ بِحنينٍ جَارِفٍ إلِى تِلْكَ الأماكِنِ الَّتي أمْضى فيها مُدَّةً مِنَ الزَّمَنِ، فإِذا ما مرَّ بِها؛ وَقَفَ بِأطْلالِها يَتَذكَّرُ أيّامَها الخَوالي.","وَقالَ الشّاعرُ العَبّاسِيُّ أبو تمّامٍ:","كمْ مَنْزلٍ فِي الأرْضِ يَأْلَفُه الفَتى وَحَنينُه أبَداً لِأوَّلِ مَنْزِلِ","وَهذا رَسولُنا مُحمَّد يَقولُ وَهوَ يُودِّع مَكَّةَ مُهاجِراً: \"وَاَللّهِ إنَّكٌِ لَخَيْرُ أرْضِ اللّهِ، وَأحَبُّ أرْضِ اللّهِ إلى اللّهِ، وَلَوْلا أنّي أخْرِجْتُ مِنْكِ ما خَرَجْتُ\".","وَما يَزالُ قَولُ الشّاعرِ أحْمدَ شَوقي ماثِلاً في الذّاكِرَةِ، حَيثُ يَقول:ُ","وَطَني لْو شُغِلْتُ بالخُلْدِ عنْه نازَعَتْني إلِيْهِ في الخُلْدِ نَفْسي","وَلا يَقْتَصِرُ حبُّ الوَطنِ عَلى الشُّعراءِ والأدَباءِ، وأصْحابِ العواطِفِ الجيّاشَةِ، فَجَبابِرَةُ التّاريخِ والقادةُ العَسْكريّونَ قدْ خامرَهُم هذا الإِحْساسُ الرَّفيعُ، فَهذا (نابُلْيونُ بونابرتْ) القائدُ الفَرنسيُّ الشَّهيرُ يَقولُ وَهُو عَلى سَريرِ المَرَضِ في مَنْفاهُ في جَزيرةِ هيلانةَ: \"خُذوا قَلبْي لِيُدْفَنَ في فَرنْسا\"، بل إنَّ الأمْرَ لمْ يقفْ عِنْدَ هذا الحدِّ، حتّى وَصَلَ إلِى درجةِ أنْ يَرى بَعْضُهم أنَّ لِلْمَوتِ في الوَطَنِ طَعْماً يَخَتَلِفُ عَنْ طَعْمِهِ بَعيداً عَنهُ، فَيقولُ الشّاعِرُ القَرَوِيّ:","أخْتَ العُروبَةِ هَيِّئي كَفَني أنا عائِدٌ لِأموتَ في وَطَني","وَلَيْسَ أقْدَرَ على الإِحْساسِ بِقيمةِ الوَطَنِ أكْثرُ مِمَّنْ كابَدَ مَواجِعَ الإِبعادِ أوِ الابْتِعادِ عَنْهُ، فَهوَ يَعيشُ على هَوامشِ أوْطانِ الآخرينَ يَتَجرَّعُ كَأسَ الغُربَةِ، وَيَتَذوَّقُ مرَارةَ الحِرْمانِ، وَلِذلكَ تَجدُ الأدَباءَ والشُّعراءَ والمُفكِّرينَ الفِلَسْطينيّينَ في مَواقعِ الشَّتاتِ يُعبِّرونَ عَن مُغالَبَتِهم حَنينَهُم إلِى وطَنهِم فِلَسْطينَ، يُفَتِّشونَ عَنْها في دَفاترِ الزَّمَنِ وَأزِقَّةِ الذّاكِرةِ، يَحْدوهُمُ الأمَلُ في العَوْدَةِ إلِيْها، طالَ الزَّمنُ أمْ قَصُرَ."],"voc":[["سُوَيداءُ القَلْبِ","حَبَّتُهُ، وَمُهْجَتُهُ، وَعُمْقُهُ."],["تَدَثَّرْنا","تَغَطيّنا."],["الكَلَأ","العُشْب."],["أطْلالها","بَقاياها."],["يَأْلَفُهُ","يَعْرِفُهُ."],["الجيّاشَة","الغَزيرَة."]],"img":[["p1-73.webp",73],["p1-74.webp",74],["p1-75.webp",75],["p1-76.webp",76],["p1-77.webp",77]]},"poem":{"t":"بِلادي","pg":78,"verses":[["بِلادي هَواها في لِساني وَفي دَمي","يُمَجِّدُها قَلْبي وَيَدْعو لَها فَمي"],["وَلا خَيْرَ فيمَنْ لا يُحِبُّ بِلادَهُ","وَلا في حَليفِ الحُبِّ إِنْ لَمْ يُتَيَّمِ"],["ألَمْ تَرَ أنَّ الطَّيرَ إِنْ جاءَ عُشَّهُ","فَآواهُ في أكْنافِهِ يَتَرنَّمِ"],["وَلَيْسَ مِنَ الأوْطانِ مَنْ لَمْ يَكُن لَها","فِداءً، وَإِنْ أمْسى إِلَيْهِنَّ يَنْتَمي"],["عَلى أنَّها لِلنّاسِ كَالشَّمْسِ لَمْ تَزلْ","تُضيءُ لَهُمْ طُرّاً وَكَمْ فيهِمُ عَمِي"],["وَمَنْ يَظْلِمِ الأوْطانَ أو يَنْسَ حَقَّها","تُجِبْهُ فُنونُ الحادثاتِ بِأظْلمِ"],["وَلا خَيْرَ فيمَنْ إِنْ أحَبَّ دِيارَهُ","أقامَ لِيبكي فَوقَ رَبْعٍ مُهَدَّمِ"],["وَما يَرْفَعُ الأوْطانَ إلّا رِجالُها","وَهَلْ يَتَرقَّى النّاسُ إِلّا بِسُلَّمِ"],["وَمَنْ يَكُ ذا فَضْلٍ فَيَبْخَلْ بِفَضْلِهِ","عَلى قَوْمِهِ يُسْتَغْنَ عَنْهُ وَيُذْمَمِ\"ِ"]],"voc":[["حَليفِ","مُتَعاهِدِ."],["أكْنافِهِ","جَوانِبِه"],["يَتَرنَّمِ","يَتَغَنّى."],["طُرّاً","جَميعاً."],["الحادثاتِ","مَصائِبِ الدَّهْرِ."],["رَبْعٍ","مَكانٍ."]],"img":[["p1-78.webp",78],["p1-79.webp",79]]},"grammar":{"t":"الضَّمائِرُ المُتَّصِلَةُ بِالفِعْلِ الماضي","pg":80,"pts":["تتّصل بالفعل الماضي ضمائرُ رفع: تاءُ الفاعل (كتبْتُ)، وألفُ الاثنين (كتبا)، وواوُ الجماعة (كتبوا)، ونونُ النّسوة (كتبْنَ)، و«نا» الفاعلين (كتبْنا).","ويتّصل به ضمائرُ نصب: الهاء والكاف والياء مع نون الوقاية (أكرمَه، أكرمَك، أكرمَني)."],"img":[["p1-80.webp",80],["p1-81.webp",81]],"q":[["الضّميرُ المتّصلُ في «أحْبَبْنا وطنَنا» (في الفعل):",["نا الفاعلين","واو الجماعة","تاء الفاعل","نون النّسوة"],0,""],["الضّمير في «الطّالباتُ دافعْنَ عن الحقّ»:",["نون النّسوة","نا الفاعلين","ألف الاثنين","تاء التّأنيث"],0,""],["الضّمير في «الصّديقان تعاونا»:",["ألف الاثنين","واو الجماعة","تاء الفاعل","لا ضمير"],0,""]]},"imla":{"t":"مِنْ مَواضِعِ حَذْفِ الألِفِ","pg":83,"pts":["من مواضع حذف الألف: من «ما» الاستفهاميّة المجرورة (لِمَ، عَمَّ، بِمَ)، ومن «ال» إذا دخلت عليها اللّام (لِلْبيت)، ومن بعض أسماء الإشارة (هذا، ذلك، هؤلاء)، ومن لفظ الجلالة (الله) و(إله، الرّحمن، لكن)."],"img":[["p1-83.webp",83]]},"khatt":{"t":"حرفا (م، و)","pg":84,"pts":["حرفا (م، و) بخطّ النَّسخ."],"img":[["p1-84.webp",84]]},"taabir":{"t":"تَلْخيصُ نَصٍّ","pg":85,"pts":["تلخيصُ نصّ."],"img":[]}},"listen":"العَوْدَةُ إِلى الجُذورِ"},{"id":"P1U8","part":1,"n":8,"sec":{"read":{"t":"خُلُقُ الاعْتِذارِ","pg":87,"paras":["أوْصى حَكِيمٌ ابنَه قائِلاً: أيْ بُنَيَّ، اعْلَمْ أنَّ الإِنْسانَ مُعرَّضٌ لِلْخَطَأ، صَغيراً كانَ أمْ كَبيراً،عالِماً أمْ جاهِلاً، وهذا الخَطَأ قَدْ يُؤْذي غَيرَه؛ ما يُؤَدِّي إِلى سوءِ العاقِبَةِ، وانْفِصامِ عُرى المَوَدَّةِ بَينَ النَّاسِ؛ لِذا حثَّنا الإِسْلامُ عَلى تَحَرّي الصَّوابِ فِي أقْوالِنا وَأفْعالِنا، وحَذَّرَنا مِن ارْتِكابِ ما يوقِعُنا فِي مَواطِنِ الحَرَجِ. وَلِأنَّ الإِنْسانَ خَطّاءٌ بِطَبْعِهِ؛ فَقَدْ قالَ رَسولُنا : \"كُلُّ ابْنِ آدمَ خَطّاءٌ، وخَيْرُ الخَطّائينَ التَّوّابونَ\". وَهُوَ الَّذي أمَرَ أبا ذَرٍّ الغِفارِيَّ أنْ يَعْتَذِرَ لِبِلالٍ بْنِ رَباحٍ حينَ عَيَّرَهُ بِأمِّهِ قائِلاً: يا بْنَ السَّوْداءِ، فَما كانَ مِنْ أبي ذَرٍّ إِلّا أنْ وَضَعَ خَدَّهُ عَلى الثّرى طالِباً مِنْ بِلالٍ أنْ يَطَأهُ بِقَدَمِهِ؛ عَسَى أنْ يُكَفِّرَ بِذلِكَ عَنْ زَلَّتِهِ.","وَأضافَ الأبُ الحَكيمُ: عَلَيْكَ ألَّا تَتَمادى فِي الخَطَأ فَتُبَرِّرَهُ، بَلْ عَلَيْكَ أنْ تَعْتَرِفَ بِهِ، وَتُبادِرَ في الاعْتِذارِ عَنْهُ، وَاعْلَمْ أنَّ الاعْتِذارَ خُلُقٌ نَبِيلٌ، وَسُلوكٌ حَضارِيٌّ، يَتَّصِفُ بِهِ العُظَماءُ، ولا يُنْقِصُ مِنْ شَأْنِ صاحِبِهِ، بَلْ يُكْسِبُهُ مَحَبَّةَ النّاسِ وَاحْتِرامَهُمْ، وَهُوَ دَليلُ التَّرَبِيَةِ السَّليمَةِ، وَالشَّخَصِيَّةِ القَوِيَّةِ، لا كَما يَظُنُّ بَعْضُ النّاسِ أنَّ الاعْتِذارَ يَجْعَلُهُمْ صِغاراً فَي أعْيُنِ الآخَرينَ!","الابْنُ: وَكَيْفَ يَكونُ الاعتِذارُ؟","الأبُ: يُعْرِبُ المُخْطِئُ عَنْ نَدَمِهِ عَلى خَطَئِهِ، وَيَطْلُبُ إِلى مَنْ أخْطَأ بِحَقِّهِ أنْ يُسامِحَهُ؛ وَبِذلِكَ تَبَشُّ الوُجوهُ، وَتَصْفو النُّفوسُ، وَتَلِينُ القلوبُ، وَيَعودُ الحَقُّ إِلى صاحِبِهِ، وَيُصْبِحُ الاعْتِذارُ عَنِ الخَطَأ سُلوكاً عَفْويّاً.","الابْنُ: هَبْ أنَّ إِنْساناً أخْطَأ في حَقّي، وَجاءَني مُعْتَذِراً فَكَيْفَ أقابِلُ اعْتِذارَهُ؟","الأبُ: عَلَيْكَ يَا بُنَيَّ أنْ تُقابِلَهُ بِوَجْهٍ باشٍّ، وَتَصْفَحَ عَنْهُ دُونَ صَدٍّ وَلا صُدودٍ؛ حَتّى لا يَنْطَبِقَ عَلَيْكَ قَوْلُ الشّاعِر:ِ","إِذَا اعْتَذَرَ الجانِي مَحا العُذْرُ ذَنْبَه وَكُلُّ امْرئٍ لا يَقْبَلُ العُذْرَ مُذْنِبُ","وَلْتَعْلَمْ يا بُنَيَّ، أنَّ الاعْتِذارَ عَنِ الخَطَأ وَقَبولَهُ يُكْسِبُ رِضا اللّهِ، وَيَقْضي عَلى الخُصوماتِ وَالأحْقادِ بَيْنَ النّاسِ، وَيُشيعُ المَحَبَّةَ بَيْنَهُمْ.","الابْنُ: لَقَدْ فَهِمْتُ رِسالَتكَ يا أبي، فَاسْمَحْ لي بِالذَّهابِ إِلى صَديقي أحْمَدَ؛ لِأعْتَذِرَ مِنْهُ عَنْ خَطَأ بَدَرَ مِنّي تُجاهَهُ. فَقالَ الأبُ: بارَكَ اللّهُ فيكَ؛ لِأنَّكَ بِاعْتِذارِكَ لَهُ تَكونُ قَدْ قَدَّمْتَ القُدْوَةَ المُثْلى وَالنَّموذَجَ المُحْتَذى."],"voc":[["العاقِبة","الخاتِمة."],["عُرى","مُفْرَدُها عُرْوَة، وهي الرّابِطَةُ القَوِيّة."],["عيّره","قبَّح فِعْلَهُ وَنَسَبَهُ إلى العارِ."],["الثّرى","التُّراب النَّديّ."],["تُبَرِّرُه","تَذْكُر أسْبابَهُ."],["عفويّاً","تِلْقائيّاً طَبيعيّاً."],["صُدود","هُجْران."],["الأحْقادُ","مُفْرَدُها حقد ، وهوَ إِضمار العَداوة."],["المُثلى","مؤنّث الأمثل ، بمعنى الأحْسَن."],["المُحْتَذى","المُقْتدى به."]],"img":[["p1-87.webp",87],["p1-88.webp",88],["p1-89.webp",89],["p1-90.webp",90]]},"grammar":{"t":"مِنَ الحُروفِ","pg":91,"pts":["الحرفُ كلمةٌ لا يظهر معناها إلّا مع غيرها.","من الحروف: حروفُ الجرّ (من، إلى، عن، على، في، الباء، اللّام، الكاف)، وحروفُ العطف (الواو، الفاء، ثمّ، أو)، وحروفُ النّفي (لا، لم، لن، ما).","الحرفُ لا يقبل علامات الاسم ولا علامات الفعل."],"img":[["p1-91.webp",91],["p1-92.webp",92]],"q":[["أيُّ الكلماتِ حرف؟",["ثُمَّ","اعتذرَ","الخطأ","قلبٌ"],0,""],["حرفُ الجرّ في «اعتذرَ عن خطئه»:",["عن","اعتذر","خطئه","الهاء"],0,""],["«لم يتأخّر» نوع الحرف «لم»:",["نفيٌ وجزم","جرّ","عطف","استفهام"],0,""]]},"imla":{"t":"مِنْ مَواضِعِ حَذْفِ الواوِ","pg":93,"pts":["من مواضع حذف الواو: في بعض الأسماء مثل (داود، طاوس) تُكتب بواو واحدة."],"img":[["p1-93.webp",93]]},"khatt":{"t":"حرفا (ت، ذ)","pg":94,"pts":["حرفا (ت، ذ) بخطّ النَّسخ."],"img":[["p1-94.webp",94]]},"taabir":{"t":"كِتابَةُ يَوْمِيّاتٍ","pg":95,"pts":["كتابةُ يوميّات."],"img":[]}},"listen":"الأخْلاقُ الكَريمَةُ"},{"id":"P1U9","part":1,"n":9,"sec":{"read":{"t":"الفَتى النَّبيهُ","pg":97,"paras":["عادَ الفَتى نبيلٌ لِتَوِّهِ مِنَ المَدْرَسَةِ، بَعْدَ أنْ قَضى يوماً حافلاً بِالنَّشاطِ...، وَضَعَ حَقيبَتَهُ فَوْقَ مَكْتَبِهِ المُتَهالِكِ الَّذي يَقَعُ في حُجْرَةٍ مُنْفَرِدَةٍ فَوْقَ سَطْحِ المَنْزِلِ، وَجَلَسَ لِيَسْتَريحَ بَعْضَ الوَقْتِ بَعْدَ أنْ بَدَّلَ مَلابِسَهُ.","دَعَتْهُ أمُّهُ لِتَناوِلِ غَدائِهِ، فَنَزَلَ مِنْ حُجْرَتِهِ لِيَجِدَها تُقابِلُهُ بِابْتِسامَةٍ قائِلَةً: يبدو أنَّكَ سَعيدٌ هذا اليومَ، فَأخْبِرْني ماذا فَعَلْتَ في المدرَسَةِ؟ بَدَأ الفَتى يَحْكي، وَكَأنَّهُ على مَسْرَحٍ أمامَ جُمْهورٍ مُنْبَهِرٍ بهِ، بِكَلِماتٍ تُرْعِدُ وَتُبْرِقُ؛ واصِفاً مُشارَكَتَهُ في أداءِ مَسْرَحيَّةٍ تَناوَلَتْ مَوْضوعَ التَّعاوُنِ،وَقَد أعْجِبَ الجُمْهورُ بِأدائِهِ.","وَضَعَ الفَتى أوَّلَ لُقْمَةٍ منَ الطّعامِ في فَمِهِ، وَأخَذَ يُكْمِلُ لِأمِّهِ كَيْفَ شَرَحَ لَهُم مُدَّرِسُ التّاريخِ قِصَّةَ زَنّوبْيا مَلِكَةِ تَدْمُرَ بِطَريقةٍ شائِقَةٍ. تَبَسَّمَتْ أمُّهُ، وَوَضَعَتْ يَدَها عَلى كَتِفِهِ. فقالَ: أحْمَدُ اللّهَ أنْ حَظيتُ بِأمٍّ مِثْلِكِ، والآنَ أريدُ اللَّحاقَ بِأبِي. دَخَلَ نَبيلٌ إلِى مَزْرَعَةِ النَّخيلِ يُنادي...أبي، أيْنَ أنْتَ؟ صَدَرَ صَوْتُ صَفيرٍ عَذْبٍ كَالموسيقا جَعَلَهُ يُحَدِّدُ مَكانَ أبيهِ، ذَهَبَ إِلَيْهِ فَوَجَدَهُ يَصْنَعُ سَلَّةً صَغيرَةً مِنْ وَرَقِ النَّخيلِ، فَطَلَبَ إلى والدِهِ أنْ يُعَلِّمَهُ كَيْفَ يَصْنَعُ السِّلالَ. تَرَكَ الأبُ ما في يَدِهِ جانِباً وَهوَ يَبْتَسِم، وَقالَ لِابنهِ: حَسَناً، هيّا نَأْتِ باِلوَرَقِ؛ صَعِدَ الأبُ النَّخْلَةَ، وَقَطَعَ جَريدَةً، وَألقاها عَلى الأرْضِ، فالتَقَطَها نَبيلٌ، وَأخَذَ يَنقَعُها في الماءِ، وَيُهَيِّئُها لِصِناعَةِ سَلَّةٍ.","أمْسَكَ الوالِدُ بِالوَرَقِ المَنْقوعِ، وَأخَذَ يُعَلِّمُ ابْنَهُ صِناعَةَ السِّلالِ خُطْوَةً خُطْوَةً، إِلى أنِ انْتَهى مِنْ ذلكَ.","نَظَرَ نَبيلٌ إِلى والدِهِ وَقالَ: لا يُمْكِنُ لِوَرَقةٍ واحِدَةٍ مِنْ هذهِ الأوْراقِ أنْ تَصْنَعَ سَلَّةً، لكنَّها إِذا اجْتَمَعَتْ مَعَ غَيْرِها مِنَ الأوراقِ، وشُدَّتْ بَعْضُها إلى بَعْضٍ، فَأصْبَحَتْ سَلَّةً. أعْجِبَ واِلدُهُ بِنَباهَتِهِ، وَقالَ لَهُ: بارَكَ اللّهُ فيكَ يا وَلَدي.","أخَذَتِ الشَّمسُ تُلَمْلِمُ مَتاعَها لِتَرْحَلَ، في الوَقْتِ الَّذي أخَذَ فيهِ الفَتى هوَ الآخرُ يُلَمْلِمُ مَتاعَهُ، وَما جَمَعَهُ في الحَقْلِ، وَعاَد بِرِفْقَةِ والِدِه إلى البَيْتِ، حَيْثُ اسْتَقْبَلَتْهُما الأمُّ، وَبَعْدَ أنْ تَناوَلَ طَعامَهُ واسْتَراحَ قَليلاً،ِ أخَذَ قَلَمَهُ، وَبَدَأ يَكْتُبُ الكَلِمَةَ الَّتي سَيُشارِكُ بِها في مُسابَقَةِ الكِتابَةِ الإِبداعيَّةِ، وَبَعْدَ أنِ انْتَهى مِنَ الكِتابَةِ أقْبَلَ على أبيهِ وَأمِّهِ؛ لِيُسْمِعَهُما ما كَتَبَ: \"أيُّها المُجاهِدونَ بِعَرَقِهِم، وَبِوَقْتِهِم، وَبِمالِهِم... يا مَنْ تَحْمِلونَ سِلاحَ الصَّبرِ، وَتُضَحّونَ بِأوْقاتِكُم، وَإِنْجازاتِكُم؛ لِتَظَلَّ راياتُ قِيَمِكُم مَرْفوعةً، تُرَفْرِفُ فَوْقَ هاماتِ الشَّجَرِ... يا مَنْ تَتَصَبَّبُ جِباهُهُمْ عَرَقاً مِنْ أجْلِ أنْ تَجِدَ النَّبْتاتُ الصَّغيرةُ قَطرَةَ ماءٍ تُساعِدُها على النُّموِّ والحَياةِ. أنْتُمِ الَّذينَ لا يَنْقَطِعُ ذِكْرُكُم عن لِسانِي، وَلا تَنْقَطِعُ ذِكْراكُم عَن ذاكِرَتي، بَلْ أظَلُّ أسْتَنْشِقُ عَبَقَكُم المُهَدِّئَ لِلنَّفْسِ المُتْعَبَةِ. إنَّ الأبُوَّةَ فَنٌّ لا يُتْقِنُهُ إِلّا عَباقِرَةُ الأبُوَّةِ، وَأنْتُمْ صُنّاعُ العَبْقَريَّةِ\".","بَعْدَ أنِ انْتَهى الفَتى مِنْ خُطْبَتِهِ (العَصْماءِ) نَظَرَ إِلى والديْهِ...كانَ والدُهُ يَحْني بِرَأْسِهِ، فيما كانَتْ أمُّهُ تَذْرِفُ دَمْعَةً."],"voc":[["لِتَوِّهِ","لِلَحْظَتِهِ."],["المُتَهالِك","القديم."],["مُنْبَهِر","مُعْجَب."],["نَباهَتِه","ذَكائِه."],["هاماتُ","مفردُها هامَة، وهي الرأس."],["عبقكم","رائحتكم الزكيَّة."],["العَصماء","البليغة."]],"img":[["p1-97.webp",97],["p1-98.webp",98],["p1-99.webp",99],["p1-100.webp",100],["p1-101.webp",101]]},"grammar":{"t":"حَرْفا الاسْتِفْهامِ: (هَلْ، أ)","pg":102,"pts":["«هل» حرفُ استفهامٍ يُسأل به عن مضمون الجملة، وجوابه «نعم» أو «لا».","الهمزة «أ» حرفُ استفهام يُسأل به عن مضمون الجملة فيُجاب بنعم أو لا، أو عن مفردٍ فيُجاب بالتّعيين (أنبيلٌ عادَ أم أخوه؟)."],"img":[["p1-102.webp",102],["p1-103.webp",103]],"q":[["جوابُ «هل حضرَ نبيلٌ؟»:",["نعم أو لا","نبيل","أمس","في البيت"],0,""],["«أزيتونًا زرعتَ أم تينًا؟» جوابه بـ:",["التّعيين: زيتونًا","نعم","لا","بلى"],0,"سُئل عن مفرد مع «أم»."],["أيُّ الحرفين يدخل على المفرد مع «أم» المعادلة؟",["الهمزة","هل","كلاهما","لا أحد"],0,""]]},"imla":{"t":"إِمْلاءٌ اخْتِبارِيٌّ","pg":105,"pts":["إملاءٌ اختباريّ."],"img":[["p1-105.webp",105]]},"khatt":{"t":"حرفا (ق، ة)","pg":106,"pts":["حرفا (ق، ة) بخطّ النَّسخ."],"img":[["p1-106.webp",106]]},"taabir":{"t":"تَكْوينُ مَوْضوعٍ مِنْ أحْداثٍ يَوْمِيَّةٍ","pg":106,"pts":["تكوينُ موضوعٍ من أحداثٍ يوميّة."],"img":[["p1-106.webp",106]]}},"listen":"مِنْ وَصايا لُقْمانَ الحَكيمِ لابْنِهِ"},{"id":"P1U10","part":1,"n":10,"sec":{"read":{"t":"مِنْ لآلِئِ العَرَبِيَّةِ","pg":108,"paras":["يُوافِقُ يَوْمُ الثّامِنَ عَشَرَ مِنْ شَهْرِ كَانُونَ الأوّلِ مِنْ كُلِّ عامٍ اليَومَ العالَمِيَّ لِلُّغةِ العَرَبِيَّةِ، وَهُوَ اليَومُ الَّذي خَصَّصَتْهُ مُنَظَّمَةُ الأمَمِ المُتّحِدَةِ لِلتَّربيةِ وَالثّقافَةِ وَالعُلومِ (يونسكو) لِلاحْتِفالِ بِاللُّغَةِ العَرَبِيَّةِ؛ لِكَوْنِهِ اليَوْمَ الَّذي أصْدَرَتْ فيهِ الجَمْعِيَّةُ العامَّةُ لِلأمَمِ المُتَّحِدَةِ قَراراً يَنُصُّ عَلى إِدْخالِ اللُّغَةِ العَرَبِيَّةِ ضِمْنَ اللُّغاتِ الرَّسْمِيَّةِ، لِغاياتِ العَمَلِ الَّتي يَتِمُّ التَّداولُ بِها في مُؤسَّساتِ الأمَمِ المُتَّحِدَةِ.","يَعودُ اهْتِمامُ الأمَمِ المُتَّحِدَةِ لِلاحْتِفالِ بِاللُّغَةِ العَرَبِيَّةِ إِلى أسْبابٍ مِنْها: أنَّها لُغَةُ كِتابٍ سَماوِيٍّ يُؤْمِنُ بِهِ مِئاتُ المَلايينِ مِنَ البَشَرِ في شَتّى بِقاعِ الأرْضِ، كَما أنَّ عَدَدَ النّاطِقينَ بِها يَتَجاوَزُ أرْبعَمِئةٍ وَخَمْسينَ مِلْيوناً مِنَ النَّاسِ، وَهي لُغَةٌ تَتَّسِمُ بِثراءِ مُفْرَداتِها وَألفاظِها، إِضافَةً إِلى أنَّها تَمْتَلِكُ خَواصَّ جَمالِيَّةً مُمَيَّزَةً، وَمِنْ أظْهَرِ هَذِهِ الخَواصِّ الخَطُّ الَّذي تُكْتَبُ بِهِ، حَيْثُ يُشكِّلُ عِقْداً مِنَ اللَّآلِئِ يُزيِّنُ جيدَها، وَيُميِّزُها عَنْ غَيْرِها مِنَ اللُّغاتِ.","يُعَدُّ الخَطُّ العَرَبَيُّ مِنَ الخُطوطِ القَديمَةِ، وَظَلَّ يَتَطَوَّرُ عَبْرَ العُصورِ وَالأزْمانِ، إِلى أنِ ازْدَهَرَ وَأصْبَحَ عِلْماً لَهُ قَواعِدُ وَأصولٌ يُمْكِنُ تَعَلُّمُها، وَهُوَ كَذلِكَ فَنٌّ لَهُ لَمَساتُهُ الجَمالِيَّةُ؛ بِما تَنْفَرِدُ بِهِ حُروفُ اللُّغَةِ العَرَبِيَّةِ المُتَّصِلَةُ بَعْضُها بِبَعْضٍ؛ لِذا تَبارى مَهَرَةُ الخَطِّ العَرَبِيِّ في إِبْداعِ لَوْحاتٍ جَمالِيَّةٍ ازْدَانَتْ بِها جُدْرانُ المَساجِدِ، وَالكَنائِسِ، وَالقُصورِ...، كَما تَنافَسَ فَنّانو الخَطِّ العَرَبِيِّ في رَسْمِ القُرْآنِ الكَريمِ الَّذي فَجَّرَ طاقاتِهِم وِإبْداعاتِهِم الفَنِّيَّةَ؛ فَنَسَخوهُ بِأبْهى الخُطوطِ وَأجْمَلِها؛ فَكانَ الرَّسْمُ العُثْمانِيُّ؛ وَبِذلكَ حُفِظَ القُرْآنُ الكَريمُ بِالخَطِّ العَرَبِيِّ.","لَقَدْ أبْدَعَ الفَنّانُونَ خُطوطاً مُتَنَوِّعَةً، مِنْ أشْهَرِها خَطُّ النّسْخِ، الَّذي سُمِّيَ بِهذا الاسْمِ؛ لِكَثْرَةِ اسْتِعْمالِهِ في نَسْخِ الكُتُبِ، وَكَذلِكَ خَطُّ الرُّقْعَةِ الَّذي كانَ يُسْتَخْدَمُ في الشُّؤونِ الإِدارِيَّةِ الَّتي كانَتْ تُكْتَبُ عَلى الرُّقاعِ؛ لِذلِكَ كانَتْ هذِهِ التَّسْمِيَةُ، وإِضافَةً إِلى هذَيْنِ الخَطَّيْنِ هُناكَ الخَطُّ الدّيوانِيُّ، وَالكوفِيُّ، وَالفارِسِيُّ، وَخَطُّ الثُّلُثِ.","وَجَمالُ الخَطِّ مَوْهِبَةٌ تَحْتاجُ إِلى دُرْبَةٍ وَطولِ مِرانٍ، وَيَتِمُّ ذلِكَ بِمُراعاةِ أمورٍ، مِنْها: اخْتيارُ المَكَانِ المُناسِبِ لِلكِتابَةِ، وَمَسْكُ القَلَمِ بطَريقَةٍ صَحيحَةٍ، وَالوَضْعُ الصَّحيحُ لِلذِّراعِ، والالتِزامُ بَقَواعِدِ الكِتابَةِ الصَّحيحَةِ.","وَيُلْحَظُ في أيّامِنا هذِهِ عُزوفُ الكَثِيرِ مِنْ طَلَبَةِ المَدارِسِ وَالجامِعاتِ وَغَيْرِهِم عَنْ مُمارَسَةِ الكِتابَةِ بِالقَلَمِ؛ لِوُجودِ وَسائِلَ تِقْنيَّةٍ تُغْني عَنِ اسْتِخْدامِهِ؛ الأمْرُ الَّذي أدَّى إِلى رَداءَةِ الخُطوطِ بِشَكْلٍ عامٍّ.","وَمِنْ هُنا يَنْبَغي أنْ تَهْتَمَّ الأسْرَةُ وَالمَدْرَسَةُ وَالجامِعاتُ وَغَيْرُها، بِتَحْسينِ خُطوطِ الأبْناءِ وَالطَّلَبَةِ؛ لِأنَّ الخَطَّ الجَميلَ يُقَوِّي حُجَّةَ صاحِبِهِ، وَفي ذلِكَ قالَ الإِمامُ عَلِي( ٌّ): \"الخَطُّ الحَسَنُ يَزِيدُ الحَقَّ وُضوحاً\"."],"voc":[["التَّداولُ بِها","اسْتِخْدامُها."],["ثَراءُ","غِنى."],["جيدَها","عُنُقَها."],["الرُّقاعُ","مُفْرَدُها رُقْعَةٌ، وَهي القِطْعَةُ مِنْ الجِلْدِ."],["عُزوف","ابْتِعاد."],["حُجَّةٌ","دَليلٌ وَبُرْهانٌ."]],"img":[["p1-108.webp",108],["p1-109.webp",109],["p1-110.webp",110],["p1-111.webp",111],["p1-112.webp",112]]},"poem":{"t":"اللُّغَةُ العَرَبِيَّةُ","pg":113,"verses":[["رَجَعْتُ لِنَفْسِي فَاتَّهَمْتُ حَصاتي","وَنادَيْتُ قَوْمي فَاحْتَسَبْتُ حَياتي"],["رَمَوْني بِعُقْمٍ فِي الشَّبابِ وَلَيْتَني","عَقِمْتُ فَلَمْ أجْزَعْ لِقَوْلِ عُداتي"],["وَسِعْتُ كِتابَ اللّهِ لَفْظَاً وَغايةً","وَما ضِقْتُ عَنْ آيٍ بِهِ وَعِظاتِ"],["فَكَيْفَ أضيقُ اليَوْمَ عَنْ وَصْفِ آلَةٍ","وَتَنْسِيْقِ أسْماءٍ لِمُخْتَرَعاتِ؟"],["أنا البَحْرُ في أحْشَائِهِ الدُّرُّ كامِنٌ","فَهَلْ سَألوا الغَوّاصَ عَنْ صَدَفاتي"],["فَيا وَيْحَكُم أبْلَى وَتَبْلَى مَحاسِني","وَمِنْكُم وَإِنْ عَزَّ الدَّواءُ أساتي"],["أرى لِرِجالِ الغَرْبِ عِزّاً وَمَنَعَة","وَكَمْ عَزَّ أقْوامٌ بِعِزِّ لُغاتِ"],["أرى كُلَّ يَوْمٍ بِالجَرائِدِ مَزْلَقاً","مِنَ القَبْرِ يُدْنيني بِغَيْرِ أناةِ"],["أيَهْجُرُني قَوْمي عَفا اللّه عَنْهُمُ","إِلى لُغَةٍ لَمْ تَتَّصِلْ بِرُواةِ؟"],["إِلى مَعْشَرِ الكُتّابِ وَالجَمْعُ حافِلٌ","بَسَطْتُ رَجائي بَعْدَ بَسْطِ شَكاتي"]],"voc":[["حَصاتي","رَأْيي وَعَقْلي."],["عُداتي","أعْدائي."],["آيٍ","آيات."],["أساتي","مُفْرَدُها آسٍ، وَهُوَ الطَّبيبُ."],["مَنَعَةً","حِمايَةً."],["مَزْلَقاً","مَكان الانْزِلاقِ."],["أناةُ","التَّأني وَالإِبْطاء."],["حافِلٌ","كَثيرٌ وَحاشِدٌ."],["شَكاتي","شَكْوايَ."]],"img":[["p1-113.webp",113],["p1-114.webp",114]]},"grammar":{"t":"مُراجَعَةٌ","pg":115,"pts":["مراجعةٌ لعلامات الإعراب الأصليّة، والمثنّى، والجموع، وإعراب المضارع، والفعل المجرّد والمزيد، والضّمائر المتّصلة، والحروف، وحرفي الاستفهام."],"img":[["p1-115.webp",115],["p1-116.webp",116]],"q":[]},"imla":{"t":"مُراجَعَةٌ","pg":118,"pts":["مراجعةٌ لهمزتي الوصل والقطع ومواضع حذف الألف والواو."],"img":[["p1-118.webp",118]]},"khatt":{"t":"حرفا (ش، ي)","pg":118,"pts":["حرفا (ش، ي) بخطّ النَّسخ."],"img":[["p1-118.webp",118]]},"taabir":{"t":"كِتابَةُ لافِتاتٍ","pg":119,"pts":["كتابةُ لافتات."],"img":[]}},"listen":"فَصاحَةٌ وَمَلاحَةٌ"},{"id":"P2U1","part":2,"n":1,"sec":{"read":{"t":"فَضائِلُ بَيْتِ المَقْدِسِ","pg":5,"paras":["تَتَعدَّدُ فَضائِلُ بَيتِ المَقْدِسِ، الأرَضِ الّتي بارَكَها اللهُ تعالى،","وَقَدَّسَها؛ فلا تُذكَرُ في كِتابِ اللهِ إلّا قُرِنَتْ بِلَفْظِ البَرَكَةِ، أوِ","﴿ :القَداسَةِ، إِذْ قالَ تَعالى","وَوَرَدَ فَضْلُ بيتِ المَقْدِسِ في السُّنَّةِ النَّبَويةِ كذلك، وَهذِهِ طائِفَة","تُؤَكِّدُ على فَضْلِ بيتِ المَقْدِسِ، ِمِنْ أحاديثِ رَسولِ الله","رَسولَ اللَّهِ: أيُّ مَسْجِدٍ وُضِعَ أوَّلَ؟ قالَ: الْمَسْجِدُ الْحَرامُ، قُلْتُ:","ثُمَّ أيٌّ؟ قالَ: ثُمَّ الْمَسْجِدُ الْأقْصى. قُلْتُ: كَمْ كانَ بَيْنَهُما؟ قالَ:","أرْبَعونَ سَنَةً، ثُمَّ قالَ: حَيْثُما أدْرَكَتْكَ الصَّلاةُ فَصَلِّ، والْأرْضُ لَكَ","أوْ مَسْجِدُ بَيْتِ الْمَقْدِسِ؟ فَقالَ ِأفْضَلُ: مَسْجِدُ رَسولِ اللَّه،","صَلاةٌ في مَسْجِدي هذا أفْضَلُ مِنْ أرْبَعِ صَلَواتٍ ِرَسولُ اللَّه:","فيهِ، وَلَنِعْمَ الْمُصَلّى هُوَ، وَلَيوشِكَنَّ أنْ يَكونَ لِلرَّجُلِ مِثْلُ شَطَنَِ","فَرَسِهِ مِنَ الأرْضِ حَيْثُ يَرى مِنْهُ بَيْتَ الْمَقْدِسِ خَيْرٌ لَهُ مِنَ الدُّنْيا ج","عَلى الْحَقِّ ظاهِرينَ، لَعَدوهِمْ قاهِرينَ، لا يَضُرُّهُمْ مَنْ خالَفَهُمْ إِلّا ما","أصابَهُمْ مِنْ لأواءَ حَتى يأتيهُمْ أمْرُ اللَّهِ وَهُمْ كَذَلِكَ، قالوا يا رَسولَ","الْمَقْدِسِ، فَقالَ: أرْضُ الْمَنْشَرِ والْمَحْشَرِ، ائْتوهُ، فَصَلّوا فيهِ، فإِنَّ","صَلاةً فيهِ كألْفِ صَلاةٍ فيما سِواهُ، قالَتْ: أرَأيْتَ مَنْ لَمْ يُطِقْ أنْ","يَتَحَمَّلَ إِلَيْهِ، أوْ يَأْتِيَهُ، قالَ: فَلْيُهْدِ إِلَيْهِ زَيْتًا يُسْرَجُ فيهِ، فَإنَّ مَنْ","أهْدى لَهُ كانَ كَمَنْ صَلّى فيهِ\"."],"voc":[["(الإ سراء","١)"],["شَطَنِ فَرَسِه","الحَبْلِ الطّويلِ تُشَدُّ بِهِ الفَرَسُ."],["لَأْواءَ","شِدَّةً."],["أفْتِنا","قَدِّمْ لَنا الفَتْوى."]],"img":[["p2-5.webp",5],["p2-6.webp",6],["p2-7.webp",7],["p2-8.webp",8]]},"grammar":{"t":"عَلاماتُ الإِعْرابِ الفَرْعِيَّةُ","pg":9,"pts":["العلامات الفرعيّة: المثنّى يُرفع بالألف ويُنصب ويُجرّ بالياء.","جمعُ المذكّر السّالم يُرفع بالواو ويُنصب ويُجرّ بالياء.","جمعُ المؤنّث السّالم يُنصب بالكسرة بدل الفتحة.","الأسماءُ الخمسة (أبو، أخو، حمو، فو، ذو) تُرفع بالواو وتُنصب بالألف وتُجرّ بالياء."],"img":[["p2-9.webp",9],["p2-10.webp",10]],"q":[["«إنّ أباك كريم»: علامة نصب «أباك»:",["الألف","الفتحة","الياء","الواو"],0,"من الأسماء الخمسة."],["«حضرَ المصلّون»: علامةُ رفع «المصلّون»:",["الواو","الضّمّة","الألف","النّون"],0,""],["«رأيتُ الطّالباتِ»: علامةُ النّصب:",["الكسرة نيابةً عن الفتحة","الفتحة","الياء","الألف"],0,""]]},"imla":{"t":"مِنَ الأحْرُفِ الَّتي تُكْتَبُ وَلا تُلْفَظُ","pg":12,"pts":["من الأحرف الّتي تُكتب ولا تُلفظ: ألفُ التّفريق بعد واو الجماعة (كتبوا)، والألفُ في «مائة»، والواو في «عمرو» و«أولئك» و«أولو»."],"img":[["p2-12.webp",12]]},"khatt":{"t":"حرفا (ر، ت)","pg":14,"pts":["حرفا (ر، ت) بخطّ الرُّقعة."],"img":[["p2-14.webp",14]]},"taabir":{"t":"مُقارَنَةٌ بَيْنَ رَجُلَيْنِ","pg":15,"pts":["مقارنةٌ بين رجلين."],"img":[]}},"listen":"حُبُّ العَمَلِ"},{"id":"P2U2","part":2,"n":2,"sec":{"read":{"t":"أطْفالُنا أكْبادُنا","pg":17,"paras":["الأبْناءُ قُرَّةُ عَيْنِ الإِنْسانِ في حَياتِهِ، وَبَهْجَتُهُ في عُمْرِهِ، وأنْسُهُ في عَيْشِهِ، بِهِمْ تَحْلو الحَياةُ، وَعَلَيْهِمْ تُعَلَّقُ الآمالُ. هُمْ ضَجيجٌ يَدُقُ الأرْضَ؛ لِتَبْقى مُسْتَيْقِظَةً، وَهُمُ الضَّمانَةُ الوَحيدَةُ لِبَقاءِ هذا العالَمِ، والمَوْسِمُ المُسْتَمِرُّ، وَحِكايَةُ الأيّامِ القادِمَةِ؛ لِذلِكَ نَقولُ: إِنَّهُمْ أوَّلاً.","غَيْرَ أنَّ ذلِكَ يَفْرِضُ عَلى الآباءِ حُسْنَ تَرْبِيَتِهِمْ، وَتَنْشِئَتِهِمُ النَّشْأةَ الصّالِحَةَ الَّتي تَجْعَلُهُمْ لَبِناتٍ صالِحَةً.","وأساسُ ذلِكَ كُلِّهِ المُعامَلَةُ، وَلِذلِكَ قيلَ: إِنَّ مُعامَلَةَ الأطْفالِ فَنٌّ يَسْتَعْصي عَلى كَثيرٍ مِنَ الآباءِ والأمَّهاتِ في فَتْرَةٍ مِنْ فَتَراتِ الحَياةِ، وَكَثيراً ما يَتَساءَلُ الآباءُ عَنْ أجْدى السُّبُلِ في التَّعامُلِ مَعَ أبْنائِهِمْ.","لَقَدْ ثَبَتَ بِشَكْلٍ قاطِعٍ تَأْثيرُ السِّنينَ الأولى مِنَ العُمْرِ في باقي حَياةِ الإِنْسانِ، فإحْساسُ الطِّفْلِ بِنَفْسِهِ يَأْتي مِنْ خِلالِ مُعامَلَةِ والِدَيْهِ لَهُ، فإنْ هُما أشْعَراهُ بِأنَّهُ (وَلَدٌ طَيِّبٌ) مَثَلاً، وَبِمَحَبَّتِهِما لَهُ؛ فإنَّهُ سَيَنْشأ طَيِّباً، وإنْ هُما أشْعَراهُ بِأنَّهُ بخلافِ ذلِكَ، وانْهالا عَلَيْهِ بِاللَّوْمِ والتَّوْبيخِ؛ فإنَّهُ سَيَنْشأ غَيْرَ طَيِّبٍ، وَيَنْتَهي بِهِ الأمْرُ إِلى الكآبَةِ والإِحْباطِ، أوْ إِلى التَّمَرُّدِ والعِصْيانِ.","إِنَّ مِنْ أخْطَرِ ما يَلْجأ إِلَيْهِ بَعْضُ الآباءِ في مُعامَلةِ أطْفالِهِمْ العُنْفَ، سَواءٌ أكانَ ذلِكَ عُنْفاً جَسَدِيّاً أوْ لَفْظِيّاً. إِنَّهُم يَلْجَؤونَ إِلى ذلِكَ؛ ظَنّاً مِنْهُم أنَّ هذا الأسْلوبَ يُؤتي ثِمارَهُ بِتأديبِهِم وَطاعَتِهِمْ لِوالِدَيْهِمْ، أمّا العُنْفُ الجَسَدِيُّ، فَيَكونُ بِضَرْبِهِم في أماكِنَ مُخْتَلِفَةٍ مِنْ أجْسادِهِمْ، أوْ بِصَفْعِهِم عَلى وُجوهِهِمْ، أوْ غَيْرِ ذلِكَ...، في حينِ يكونُ العُنْفُ اللَّفْظِيُّ، بِتَوْجيهِ الكَلِماتِ والألفاظِ المُسيئَةِ الَّتي تَحْمِلُ مَعانيَ السُّخْرِيَةِ والاسْتِهْزاءِ والإ هانَةِ.","لَقَدْ نادَتِ الشَّرائِعُ السَّماويَّةُ بِضَرورَةِ العَطْفِ عَلى الأطْفالِ، والرِّفْقِ ( َبِهِمْ، وَمُعامَلَتِهِمْ بِالرَّحْمَةِ والحَنانِ، فَقَدْ وَرَدَ عَنْ أبي هُرَيْرَة) أنَّ ( َّالنَّبِيأقْرَعُ بْنُ -رَضِيَ اللّهُ عَنْهُما- ٍّ) قَبَّلَ الحَسَنَ بْنَ عَلِي وَعِنْدَهُ الا حابِسِ التَّمِيمِيُّ جالِساً، فَقالَ: إنَّ لي عَشَرَةً مِنَ الوَلَدِ ما قَبَّلْتُ مِنْهُمْ ( ِأحَداً، فَنَظَرَ إلَيْهِ رَسُولُ اللّه) فَقالَ:\"مَنْ لا يَرْحَمْ لا يُرْحَمْ\".","كَما أكَّدَتِ المَواثيقُ الدَّوْلِيَّةُ عَلى احْتِرامِ حُقوقِ الطِّفْلِ، فاتِّفاقِيَّةُ حُقوقِ الطِّفْلِ تَنُصُّ عَلى حَقِّهِ في العَيْشِ في أسْرَةٍ مُجْتَمِعَةِ الشَّمْلِ، كَما نَصَّتْ عَلى حَقِّهِ في التَّعْليمِ، والحِمايَةِ مِنَ العُنْفِ،وَسوءِ المُعامَلَةِ، والإِهْمالِ، سَواءً في الأسْرَةِ، أوِ المَدْرَسَةِ، أوِ المُجْتَمَعِ.","فَعَلى الآباءِ والأمَّهاتِ أنْ يَتَواضَعوا احْتِراماً أمامَ عَظَمَةِ الطُّفولَةِ، وأنْ يَفْهَموا أنَّ كَلِمَةَ (الطِّفْلِ) مُرادِفَةٌ لِكَلِمَةِ (المَلِكِ)، وأنْ يَشْعُروا بِأنَّ مَنْ يَنامُ بَيْنَ ذِراعيْهِمْ بِشَكْلِ طِفْلٍ هُوَ (المُسْتَقْبَلُ) نَفْسُهُ، وأنَّ مَنْ يَلْعَبُ الآنَ عِنْدَ أقْدامِهِمْ مُسْتَغْرِقاً في اللَّهْوِ هُوَ (التّاريخُ) عَيْنُهُ.","وَكَما أنَّ الأبُوَّةَ فَنٌّ تَتَجَلّى فيهِ حُقوقُ الطِّفْلِ، فإنَّ البُنُوَّةَ هِيَ الأخْرى فَنٌّ يَقْتَضي مِنَ الطِّفْلِ واجِباتٍ تُجاهَ والِدَيْهِ، فاحْتِرامُ الوالِدَيْنِ، وَطاعَتُهُما، وَبِرُّهُما صَغيرَيْنِ وَكَبيرَيْنِ أمورٌ فَرَضَتْها الشَّرائِعُ السَّماوِيَّةُ، فإنْ هُوَ فَعَلَ ذلِكَ، اكْتَمَلَتْ خُطوطُ اللَّوْحَةِ الفَنّيَّةِ الَّتي رَسَمَها الأبُ والابْنُ مَعاً، وَتَرَكَتْ صَدًى واسِعاً في النُّفوسِ."],"voc":[[")(المصدر","الشبكة العنكبوتية"],["قُرَّةُ عَيْن","سُرورُها."],["أجْدى","أنْفَعِ."],["صَفْعِهِم","ضَرْبِهِم."]],"img":[["p2-17.webp",17],["p2-18.webp",18],["p2-19.webp",19],["p2-20.webp",20]]},"poem":{"t":"لَيْلى","pg":21,"verses":[["تَقولُ إِذا عُدْتُ إِلَيْها مِنَ العَمَلْ","كَلاماً مِنَ الأعْماقِ أحْلى مِنَ العَسَلْ"],["تَقولُ أما أحْضَرْتَ يا أبَتي وَلَو","قَليلاً مِنَ الحَلْوى؟ فَقُلْتُ لَها: أجَلْ"],["بَحَثْتُ عَنِ الحَلْوى إِلى أنْ وَجَدْتُها","وَلَوْ لَمْ أجِدْها ما رَجَعْتُ عَلى عَجَلْ"],["إِذا طَلَبَتْ لَيْلى فُؤادي وَهَبْتُهُ","وَهَلْ لِسِواها في حَناياهُ مِنْ مَحَلّ؟"],["تُبادِلُني حُبّاً بِحُبٍّ حَقيقَةً","فَلا القَوْلُ مَكْذوبٌ وَلا الحُبُّ مُفْتَعَلْ"],["وَلكِنَّهُ الحُبُّ البَريءُ الَّذي خَلا","مِنَ الزَّيْفِ حَتّى شَفَّ بِالرّوحِ واسْتَقَلّ"],["لَها كَلِماتٌ لا أمَلُّ سَماعَها","وَمَنْ كانَ مِثْلي في الأبُوَّةِ لا يَمَلّ"],["وَما زالَ هذا الأمْرُ دأبي وَدأبَها","كأنّا عَلى أمْوالِ قارونَ نَقْتَتِلْ"]],"voc":[["وَهَبْتُها","مَنَحْتُها."],["حَناياهُ","داخِلُهُ."],["الزَّيْفِ","الغِشِّ."],["دأبي","عادَتي."]],"img":[["p2-21.webp",21]]},"grammar":{"t":"الجُمْلَةُ الاسْمِيَّةُ وَالجُمْلَةُ الفِعْلِيَّةُ","pg":22,"pts":["الجملةُ الاسميّة: تبدأ باسم، وركناها المبتدأ والخبر (الأطفالُ أكبادُنا).","الجملةُ الفعليّة: تبدأ بفعل، وركناها الفعل والفاعل (يلعبُ الأطفالُ)."],"img":[["p2-22.webp",22],["p2-23.webp",23]],"q":[["نوعُ جملة «الطّفولةُ بريئةٌ»:",["اسميّة","فعليّة","شبه جملة","لا شيء"],0,""],["نوعُ جملة «يحتضنُ الأبُ ابنَه»:",["فعليّة","اسميّة","شرطيّة","استفهاميّة"],0,""],["ركنا الجملة الاسميّة:",["المبتدأ والخبر","الفعل والفاعل","الفاعل والمفعول","الجارّ والمجرور"],0,""]]},"imla":{"t":"مِنَ الأحْرُفِ الَّتي تُلْفَظُ وَلا تُكْتَبُ","pg":24,"pts":["من الأحرف الّتي تُلفظ ولا تُكتب: الألف في (هذا، هذه، ذلك، لكنّ، الله، الرّحمن، إله، طه)، والواو في (داود، طاوس)."],"img":[["p2-24.webp",24]]},"khatt":{"t":"حرف (د)","pg":26,"pts":["حرف (د) بخطّ الرُّقعة."],"img":[["p2-26.webp",26]]},"taabir":{"t":"بِناءُ حِوارٍ بَيْنَ شَخْصَيْنِ","pg":27,"pts":["بناءُ حوارٍ بين شخصين."],"img":[]}},"listen":"الطُّفولَةُ في فِلَسْطينَ"},{"id":"P2U3","part":2,"n":3,"sec":{"read":{"t":"بَيْتُنا في الذّاكِرَةِ","pg":29,"paras":["يِبْنا بَلْدَةٌ فِلَسْطينِيَّةٌ عَريقَةٌ، صاحِبَةُ تاريخٍ وَتُراثٍ مُشْرِقٍ، شأنُها شأنُ القُرى والمُدُنِ الفِلَسْطينِيَّةِ الَّتي أرادَ الاحتِلالُ لَها أنْ تُمْحى مِنْ صَفَحاتِ التّاريخِ، وَتُلْبَسَ ثَوْباً غَيْرَ ثَوْبِها، لكِنَّها سَتَظَلُّ ماثِلَةً في ذاكِرِةِ أبْناءِ الشَّعْبِ الفِلَسْطينِيِّ الَّذي يَحْمِلُ مَعَهُ المَكانَ بِمَوْجوداتِهِ وَذِكْرَياتِهِ، فَلا يَنْساهُ أيْنَما حَلَّ، وَحَيْثُما رَحَلَ.","هيَ إِحْدى القُرى الَّتي دَمَّرَها الصَّهايِنَةُ بَعْدَ احْتِلالِهِمْ لَها في الرّابِعِ مِنْ حَزيرانَ عامَ ألفٍ وَتِسْعِمِئَةٍ وَثَمانِيَةٍ وأرْبَعينَ لِلميلادِ، تَقَعُ في الجُزْءِ الجَنوبِيِّ الغَرْبِيِّ مِنْ قَضاءِ الرَّمْلَةِ، وَتَبْعُدُ عَنِ المَدينَةِ مَسافَةَ أرْبَعَةَ عَشَرَ كيلو مِتْراً، وَعَنِ البَحْرِ المُتَوَسِّطِ سِتَّةِ كيلو مِتْراتٍ إِلى الشَّرقِ، وَكانَتْ مَحَطَّةً مَرْكَزِيَّةً في شَبَكَةِ المُواصَلاتِ بَيْنَ شَمالِ فِلَسْطينَ وَجَنوبِها، وَتُحيطُ بِها أراضي قُرى النَّبِيِّ روبينَ، والقُبَيْبَةِ، وَزَرْنوقَةَ، وَعَرَبِ صُقْريرَ، وأسْدودَ، وَبَشّيتَ.","بَلَغَتْ مِساحَةُ أراضي يِبْنا عامَ ألفٍ وَتِسْعِمِئةٍ وَخَمْسَةٍ وأرْبَعينَ لِلميلادِ حَوالَيْ سِتّينَ ألْفِ دونُمٍ؛ لِذا عُدَّتِ الزِّراعَةُ الحِرْفَةَ الرَّئيسَةَ لِأهْلِها، وَيَعودُ ذلِكَ إِلى خُصوبَةِ الأراضي الزِّراعِيَّةِ واتِّساعِها، واخْتِراقِ عَديدٍ مِنَ الأوْدِيَةِ لِأراضيها، وَكَثْرَةِ الآبارِ الارْتِوازِيَّةِ فيها. وَكانَتْ تُعَدُّ جَنَّةَ الفَواكِهِ والخَضْراواتِ، وَقَدْ قالَ عَنْها المَقْدِسِيُّ صاحِبُ كِتابِ (أحْسَنِ التَّقاسيمِ): \"هِيَ بَلَدُ التّينِ الدِّمَشْقِيِ النَّفيسِ\"، وَمِنَ المَزْروعاتِ الَّتي اشْتُهِرَتْ بِها: الزَّيْتونُ، والحُبوبُ، والأشْجارُ المُثْمِرَةُ، وَكُرومُ العِنَبِ.","وَمِنْ مَعالِمِها الأثَرِيَّةِ: جامِعُ يِبْنا الكَبيِرُ، الّذي بَناهُ الأميرُ (بُشْتاك )ُ أحَدُ مَماليكِ الظّاهِرِ مُحَمَّدِ بْنِ قَلاوونَ، وَجامِعُ أبي هُرَيْرَةَ الّذي جَدَّدَهُ السُّلْطانُ الظّاهِرُ بيبَرْس، وَكانَ رُوّادُهُما المُصَلّونَ مِنْ أهْلِ يِبْنا والقُرى المُجاوِرَةِ، أمّا الأئِمَّةُ والخُطَباءُ، فَقَدْ كانوا مِنْ خِرّيجي الأزْهَرِ الشَّريفِ، الَّذينَ اتَّخَذوا مِنَ المَسْجِدَيْنِ صُفوفاً للكُتّابِ، يُعَلِّمونَ فيهِما القُرْآنَ الكَريمَ، والحَديثَ النَّبَوِيَّ الشَّريفَ، والقِراءَةَ، والحِسابَ؛ ما أدّى إِلى انْتِشارِ الكِتابَةِ والقِراءَةِ في يِبْنا مُنْذُ العَصْرِ العُثْمانِيِّ. وَمِنْ الصَّحابِيِّ أبي قِرْصافَةَ، والشَّيْخِ وَهْدانَ، -ًأيْضا- مَعالِمِهامَقاماتُ والشَّيْخِ سَليمٍ، والسَّيِّدَةِ عائِشَةَ.","أنْشِئَتْ مَدْرَسَةٌ جَديدَةٌ في القَرْيَةِ عامَ ألْفٍ وَتِسْعِمِئةٍ وَسَبْعَةٍ وَثَلاثينَ لِلميلادِ، وَبَعْدَ عِدَّةِ سَنَواتٍ تَمَّتْ تَوْسِعَتُها؛ لِتُصْبِحَ مَدْرَسَةً كامِلَةً، وَكانَتْ تَتْبَعُها أرْضٌ مِساحَتُها ثَلاثونَ دونُماً، خُصِّصَ مِنْها قِسْمٌ لِلتَّعْليمِ الزِّراعِيِّ العَمَلِيِّ، حَيْثُ اهْتَمَّتْ هذِهِ المَدْرَسَةُ بِتَرْبِيَةِ الطُّيورِ، والدَّواجِنِ، والنَّحْلِ.","اهْتَمَّ أهالي يِبْنا بِالمَرْأةِ وَدَوْرِها في المُجْتَمَعِ، وَقَدْ تَرْجَموا اهْتِمامَهُمْ هذا بِتَبَرُّعِهِمْ بِإِنْشاءِ مَدْرَسَةٍ لِلْبَناتِ في عامِ ألْفٍ وَتِسْعِمِئةٍ وَثَلاثَةٍ وَأرْبَعينَ لِلميلادِ، وَكانَتْ تَضُمُّ أكْثَرَ مِنْ أرْبَعٍ وَأرْبَعينَ طالِبَةً.","أنْجَبَتْ يِبْنا عَدَداً مِنَ القادَةِ والمُفَكِّرينَ الَّذينَ رَفَعوا لِواءَ القَضِيَّةِ -ْمِنْ بَعْدِهِم- ُالفِلَسْطينِيَّةِ، وارْتَقَوْا شُهَداءَ وَهُمْ مُتشَبِّثونَ بِهِ؛ لِتَتَلَقَّفَه أجْيالٌ تَتَلْمَذَتْ في مَدارِسِ المُقاوَمَةِ والنِّضالِ، حامِلَةً فِلَسْطينَ بِمُكَوِّناتِها وَمُقَوِّماتِها، وَحالِمَةً بِحَقِّ العَوْدَةِ الَّذي لا بَديلَ عَنْهُ."],"voc":[["عَريقَةٌ","أصيلَةٌ."],["شأنُها","حالُها."],["ماثِلَةً","حاضِرَةً."],["دونُم","قِطْعَةٌ مِنَ الأرْض ِ، مِساحَتُها ألفُ مِتْرٍ مُرَبّعٍ."],["كُتّابِ","مُفْرَدُ كَتاتيب، وَهُوَ مَكانٌ بَسيطٌ للتَّعْليمِ الأوَّلِيّ."],["مَقامات","جَمْعُ مَقامٍ، وهو مَكانٌ بِهِ قَبْرُ وَلِيٍّ مِنْ أوْلياءِ اللّهِ الصّالِحينَ."],["مُتَشَبِّثونَ بِهِ","مُتَمَسِّكونَ بِهِ بِقُوَّةٍ."],["(عَبّاس نَمر","قُرى فِلَسْطينَ المُدَمَّرَة مَجْموعَةُ مَقالاتٍ، بِتَصَرُّفٍ)-ُ 3 1"]],"img":[["p2-29.webp",29],["p2-30.webp",30],["p2-31.webp",31],["p2-32.webp",32]]},"poem":{"t":"الشَّريدُ","pg":33,"verses":[],"voc":[["رَغَدٍ","سَعَةِ العَيشِ وَهَناءَتِهِ."],["الشُّمُّ","جَمْعُ أشَمُّ، وَتَعْني العاليةَ الشّامِخَةَ."],["أبُثُّك الحُبَّ","أظْهِرهُ لَكَ."],["سَنًى","لَمَعاناً."]],"img":[["p2-33.webp",33],["p2-34.webp",34]]},"grammar":{"t":"المُبْتَدَأُ وَالخَبَرُ (عَلاماتُ رَفْعِهِما)","pg":35,"pts":["المبتدأ والخبر مرفوعان.","علامةُ الرّفع الضّمّة إذا كانا اسمًا مفردًا أو جمعَ مؤنّثٍ سالمًا أو جمعَ تكسير.","الألف إذا كانا مثنّى، والواو إذا كانا جمعَ مذكّرٍ سالمًا أو من الأسماء الخمسة."],"img":[["p2-35.webp",35],["p2-36.webp",36]],"q":[["«الفلّاحون نشيطون»: علامة رفع الخبر:",["الواو","الضّمّة","الألف","الياء"],0,""],["«البيتان قديمان»: علامة رفع المبتدأ:",["الألف","الضّمّة","الواو","الياء"],0,""],["«الذّكرياتُ جميلةٌ»: علامة رفع المبتدأ:",["الضّمّة","الواو","الألف","الكسرة"],0,"جمع مؤنّث سالم."]]},"imla":{"t":"إِمْلاءٌ اخْتِبارِيٌّ","pg":39,"pts":["إملاءٌ اختباريّ."],"img":[["p2-39.webp",39]]},"khatt":{"t":"حرف (ك)","pg":39,"pts":["حرف (ك) بخطّ الرُّقعة."],"img":[["p2-39.webp",39]]},"taabir":{"t":"التَّعْبيرُ عَنْ صورَةٍ","pg":40,"pts":["التّعبيرُ عن صورة."],"img":[]}},"listen":"بَيْنَ الشَّجَرَةِ وَدَيْرِ ياسينَ"},{"id":"P2U4","part":2,"n":4,"sec":{"read":{"t":"قُوَّةُ الإِيمانِ","pg":43,"paras":["بَلَغَ الخَليْفَةَ العَبّاسيَّ هارونَ الرَّشيدَ أنَّ رَجُلاً مِنْ بَقايا بَني أميَّةَ بِدِمَشْقَ كَثيرُ المالِ، عَظيمُ الجاهِ، مُطاعٌ في البَلَدِ، لَهُ جَماعَةٌ وأوْلادٌ، وَمَماليكُ يَرْكَبونَ الخَيْلَ وَيَحْمِلونَ السِّلاحَ، وإنَّهُ سَمْحٌ جَوادٌ، لا يُؤْمَنُ مِنْهُ فَتْقٌ بَعْدَ رَتْقِهِ، فَعَظُمَ ذَلِكَ على الرَّشيدِ، فَقالَ لِخادِمِهِ مَنارَةَ: اخْرُجِ السّاعَةَ إِلى الرَّجُلِ، فَقَيِّدْهُ، وَجِئْ بِهِ، واحْفَظْ ما يَقولُهُ حَرْفاً حَرْفاً.","قالَ مَنارَةُ: فأتَيْتُ الرَّجُلَ، وَدَخَلْتُ بِغَيْرِ إِذْنٍ، فَلَمّا رأى أهْلُ البَيْتِ ذلِكَ، سألوا بَعْضَ مَنْ مَعِيَ عَنّي، فَلَمّا عَرَفوا أنّي رَسولُ أميرِ المُؤْمِنينَ قاموا، وَرَحَّبوا بي، فَقُلتُ: أفيكُمْ فُلانٌ؟ قالوا: نَحْنُ أوْلادُهُ، وَهوَ في الحَمّامِ، فَقُلتُ: اسْتَعْجِلوهُ، فَمَضى بَعْضُهُمْ يَسْتَعْجِلُهُ، وَلَمْ أزَلْ أنْتَظِرُ حَتّى خَرَجَ الرَّجُلُ، وَكانَ قَدِ اشْتَدَّ خَوْفي وَقَلَقي مِنْ أنْ يَخْتَفِيَ، فَجاءَ وَسَلَّمَ عَلَيَّ وَحَوْلَهُ جَماعَةٌ مِنَ الكُهولِ، وأحْداثٌ، وَصِبيانٌ هُمْ أوْلادُهُ وَغِلْمانُهُ، وَسألَني عَنْ أميرِ المُؤْمِنينَ، واسْتِقامَةِ أمْرِ حَضْرَتِهِ، فأجَبْتُهُ عَمّا سألَ.","وَما إِنْ قَضى كَلامَهُ حَتّى جاؤوا بِأطْباقِ فاكِهَةٍ، فَقالَ: تَقَدَّمْ يا مَنارَةُ فَكُلْ مَعَنا، فَلَمْ أفْعَلْ، ثُمَّ جاؤوا بِمائِدَةٍ عَظيمَةٍ لَمْ أرَ مِثْلَها إِلّا لِلْخَليفَةِ، فَقالَ أحَدُهُمْ: تَقَدَّمْ يا مَنارَةُ فَكُلْ، فَلَمْ أفْعَلْ، فَما عاوَدَني.","فَلَمّا فَرَغَ مِنْ أكْلِهِ، قامَ إِلى الصَّلاةِ، فَصَلّى، وأكْثَرَ مِنَ الدُّعاءِ، ثُمَّ قالَ لي: ما أقْدَمَكَ يا مَنارَةُ؟ فأخْرَجْتُ كِتابَ أميرِ المُؤْمِنينَ، فَدَفَعْتُهُ إِلَيْهِ، فَفَضَّهُ، وَقَرأهُ، ثُمَّ أمَرَ أوْلادَهُ بالانْصِرافِ، وَقالَ: هاتِ قُيودَكَ يا مَنارَةُ، فَدَعَوْتُ بِالقُيودِ، وَقَيَّدْتُهُ، وَحَمَلْتُهُ في شِقٍّ ِمنْ مَحْمَلِ الفَرَسِ، وَرَكِبْتُ في الشِّقِّ الآخَرِ. فَلمّا صِرْنا بِغَوْطَةِ دِمَشْقَ، مَرَرْنا بِبَساتينَ وَمَزارِعَ وَضياعٍ كَثيرَةٍ، فَقالَ لي: أتَرى هَذِهِ؟ قُلْتُ: نَعَمْ، قالَ: إِنَّها لي. وأخَذَ يُحَدِّثُني عَنْ أمْلاكِهِ، فاشْتَدَّ غَيْظي مِنْهُ، وَقُلْتُ: عَجَباً لَكَ! ألَسْتَ تَعْلَمُ أنَّ أميرَ المُؤْمِنينَ أهَمَّهُ أمْرُكَ حَتّى أرْسَلَ إِليكَ مَنِ انْتَزَعَكَ مِنْ بَيْنِ أهْلِكَ وَوَلَدِكَ، وأخْرَجَكَ مِنْ بَيْتِكَ مُقَيَّداً لا تَدْري ما يَصيرُ إِليهِ أمْرُكَ، وَأنْتَ فارِغُ القَلْبِ حتّى تَصِفَ بَساتينَكَ وَضياعَكَ؟","فَقالَ مُجيباً: أخْطأتْ فِراسَتي فيكَ، لَقَدْ ظَنَنْتُكَ رَجُلاً كامِلَ العَقْلِ، وإنَّكَ ما حَلَلْتَ مِنَ الخُلَفاءِ هَذا المَحَلَّ إِلّا بَعْدَ أنْ عَرَفوكَ بِذَلِكَ، وأمّا قَوْلُكَ في أميرِ المُؤْمِنينَ، وإِخْراجِهِ إِيّايَ إِلى بابِهِ على صورَتي هذِهِ، فَإِنّي على ثِقَةٍ هوَ الَّذي بيدِهِ ناصيَتي، وَلا يَمْلِكُ أميرُ المُؤْمِنينَ لِنَفْسِهِ وَلا لِغَيْرِهِ نَفْعاً وَلا -َّعَزَّ وَجَل- ِمِنَ اللّه ضَرّاً إِلّا بِإِذْنِ اللّهِ، ثمَّ لا ذَنْبَ لي أخافُهُ عِنْدَ أميرِ المُؤمِنينَ، وَقَدْ كُنْتُ أحْسَبُ أنَّكَ تَعْرِفُ هَذا، أمّا وَقَدْ عَرَفْتُ مَبْلَغَ فَهْمِكَ، فإِنّي لا أكَلِّمُكَ كَلِمَةً واحِدَةً حتّى تُفَرِّقَ بَيْنَنا حَضْرَةُ أميرِ المُؤْمِنينَ.","قالَ مَنارَةُ: وَدَخَلْتُ على الرَّشيدِ، وَوَقَفْتُ، فَقالَ: هاتِ ما عِنْدَكَ يا مَنارَةُ، فَسُقْتُ الحَديثَ مِنْ أوَّلِهِ إِلى آخِرِهِ. فَلَمّا جِئْتُ على آخِرِهِ قالَ: صَدَقَ واللّهِ، ما هَذا إِلّا رَجُلٌ مَحْسودٌ على النِّعْمَةِ، مَكْذوبٌ عَلَيْهِ، وَلَعَمْري لَقَدْ أزْعَجْناهُ، وآذَيْناهُ، وَرَوَّعْنا أهْلَهُ، فَبادِرْ بِنَزْعِ قُيودِهِ، وائْتِني بِهِ، فَفَعَلْتُ، وأدْخَلْتُهُ على الرَّشيدِ، فَدَنا الأمَويُّ، وَسَلَّمَ بالخِلافَةِ، فَرَدَّ عَليهِ الرَّشيدُ رَدّاً جَميلاً، وَقالَ لَهُ: بَلَغَنا عَنْكَ فَضْلُ هَيْئَةٍ وأمورٌ أحْبَبْنا مَعَها أنْ نَراكَ، وَنَسْمَعَ كلامَكَ، وَنُحْسِنَ إِليكَ، فاذْكُرْ حاجَتَكَ.","قالَ الأمَويُّ: لي حاجَةٌ واحِدَةٌ: أنْ تَرُدَّني إِلى بَلَدي، وأهْلي، وَوَلَدي.","قالَ الرَّشيدُ: يا مَنارَةُ، احْمِلْهُ مِنْ وَقْتِكَ، وَسِرْ بِهِ راجِعاً مَحْفوظاً، حتّى إِذا وَصَلْتَ إِلى مَجْلِسِهِ الَّذي أخَذْتَهُ مِنْهُ، فَدَعْهُ، وانْصَرِفْ."],"voc":[["جَوادٌ","كَريمٌ."],["الغَوْطَة","المَنْطِقَةُ المُنْخَفِضَةُ."],["فارِغ القلَبِ","لا يَشْغَلُهُ هَمٌّ."],["فِراسَتي","مَعْرِفَتي بِبَواطِنِ الامورِ بِمُلاحَظَةِ ظَواهِرِها.أ"],["مِنْ وَقْتِكَ","مِنْ هذهِ اللَّحْظَةِ."]],"img":[["p2-43.webp",43],["p2-44.webp",44],["p2-45.webp",45],["p2-46.webp",46],["p2-47.webp",47]]},"grammar":{"t":"أنْواعُ الفِعْلِ","pg":48,"pts":["الفعلُ الماضي: ما دلّ على حدوثِ الفعلِ في الزّمن الماضي (صَبَرَ).","الفعلُ المضارع: ما دلّ على حدوثه في الحاضر أو المستقبل، ويبدأ بأحد أحرف «أنيت» (يصبرُ).","فعلُ الأمر: ما يُطلب به حدوثُ الفعل بعد زمن التّكلّم (اصبِرْ)."],"img":[["p2-48.webp",48],["p2-49.webp",49]],"q":[["نوعُ الفعل «تَمَسَّكْ»:",["أمر","ماضٍ","مضارع","ليس فعلًا"],0,""],["نوعُ الفعل «يُؤْمِنُ»:",["مضارع","ماضٍ","أمر","اسم"],0,""],["نوعُ الفعل «ثَبَتَ»:",["ماضٍ","مضارع","أمر","حرف"],0,""]]},"imla":{"t":"كِتابَةُ الأسْماءِ المَوْصولَةِ (١)","pg":51,"pts":["الأسماءُ الموصولة: الّذي، الّتي، الّذين تُكتب بلامٍ واحدة؛ واللّذان، اللّتان، اللّذَيْن، اللّتَيْن، اللّائي، اللّاتي بلامين."],"img":[["p2-51.webp",51]]},"khatt":{"t":"حرفا (ز، ل)","pg":52,"pts":["حرفا (ز، ل) بخطّ الرُّقعة."],"img":[["p2-52.webp",52]]},"taabir":{"t":"كِتابَةُ قِصَّةٍ","pg":53,"pts":["كتابةُ قصّة."],"img":[]}},"listen":"عُمَرُ بْنُ عَبْدِ العَزيزِ وَالمَرْأةُ مِنَ العِراقِ"},{"id":"P2U5","part":2,"n":5,"sec":{"read":{"t":"أُمومَةٌ وَإِمامٌ","pg":55,"paras":["أثْمَنُ ما يَمْنَحُهُ الإِنْسانُ لِوَلَدِهِ أدَبٌ يَرْتَفِعُ بِهِ شأنُهُ، وَقِيَمٌ تَعْظُم بِها سيرَتُهُ، وَنَصائِحُ تُنيرُ دَرْبَهُ، وَهكَذا كانَ الإِمامُ الشّافِعِيُّ، وَهكَذا كانَتْ أمُّهُ.","وُلِدَ الإِمامُ الشّافِعِيُّ في مَدينَةِ غَزَّةَ عامَ مِئَةٍ وَخَمْسينَ لِلْهِجْرَةِ، وَقَدْ شاءَ اللّهُ أنْ يَنْشأ يَتيماً؛ إِذْ لَمْ يَمْضِ عَلى وِلادَتِهِ غَيْرُ سَنَتَيْنِ حَتّى تُوِفِّيَ أبوهُ، وَبَقِيَ في كَفالَةِ أمِّهِ، حَيْثُ نَذَرَتِ الأمُّ ابْنَها لِلْعِلْمِ، تَجوبُ بِهِ البُلْدانَ، وَتُقَدِّمُهُ إِلى الشُّيوخِ، وَتَلْتَمِسُ لَهُ مَكاناً في حَلَقاتِ العِلْمِ، حَتّى صارَ الشّافِعِيُّ هُوَ الإِمامُ الَّذي مَلَأ طِباقَ الدُّنْيا عِلْماً، وَفِقْهاً، وَبَلاغَةً، وَشِعْراً.","حَمَلَتْهُ أمُّهُ وَهُوَ ابْنُ سَنَتَيْنِ، وأتَتْ بِهِ مَكَّةَ تُعَرِّفُ أهْلَهُ بِهِ، وَتُعَرِّفُهُ بِهِمْ، إِذْ هُوَ يَنْحَدِرُ مِنْ نَسَبٍ مُطَّلِبِيٍّ قُرَشِيٍّ، وأخَذَتْ تُراوِحُ لِأجْلِ ذلِكَ بَيْنَ غَزَّةَ وَمَكَّةَ حَتّى أتَمَّ الشّافِعِيُّ عَشْرَ سِنينَ، حَيْثُ مَكَثَ عِنْدَ أهْلِهِ يَطْلُبُ العِلْمَ.","جاءَ الشّافِعِيُّ ذاتَ يَوْمٍ حَيْثُ كانَ يَتَلَقّى العِلْمَ عَلى يَدِ الإِمامِ مالِكِ بْنِ أنَسٍ إِلى مَكَّةَ لِزِيارَةِ أمِّهِ، وَعِنْدَما طَرَقَ البابَ قالَت: مَنْ أنْتَ؟ فَقالَ لَها: مُحَمَّدُ بْنُ إِدْريسَ، ثمَّ قالَتْ لَهُ: وَبِمَ جِئتَني؟ فَقالَ لَها: جِئْتُكِ بِالعِلْمِ والأدَبِ. فقالَتْ لَهُ: لَسْتَ الشّافِعيَّ، فَحارَ مِن أمْرِهِ، ثُمَّ عادَ إِلى أسْتاذِهِ وَمُعَلِّمِهِ في دارِ الهِجْرَةِ، وَقَصَّ عَلَيْهِ أمْرَهُ، فَتَبَسَّمَ الإِمامُ مالِكٌ، وقالَ لَهُ: يا شافِعِيُّ، ارْجعْ إِلى أمِّكَ، واطرُقِ البابَ، فإذا ما سألَتْكَ: مَنْ أنْتَ؟ فَقُلْ لَها: مُحَمَّدُ بْنُ إِدْريسَ، فَإِذا ما قالَتْ لَكَ: وَبِمَ جِئْتَ؟ فَقُلْ لَها: جِئْتُ بِالأدَبِ والعِلْمِ، فَفَعَلَ ذلِكَ، فَقالَت لَهُ الأمُّ: الآنَ يا شافِعِيُّ.","وَلَعَلَّنا نُلاحِظُ هُنا أنَّ الأمَّ قَدْ رَدَّتِ ابْنَها إِلى أسْتاذِهِ؛ لِيَقينِها أنَّهُ لَمْ يُدْرِكِ الهَدَفَ والغايَةَ، إِذْ قَدَّمَ لَها في المَرَّةِ الأولى العِلْمَ عَلى الأدَبِ، فَرَدَّتْهُ إِلى شَيْخِهِ؛ لِيُحْسِنَ، وَيَتَيَقَّنَ الهَدفَ مِنِ العِلْمِ وَطَلَبِهِ، وَهوَ الأدَبُ والتَّرْبِيَةُ. مِنْ أجْلِ ذلِكَ قالَ الإِمامُ الشّافِعِيُّ: تَعَلَّمْتُ مِنْ مالِكٍ الأدَبَ أضْعافَ ما تَعَلَّمْتُ العِلْمَ."],"voc":[["طِباقَ","نَواحِي"],["يَنْحَدِرُ","يَنْتَسِبُ إِلى."]],"img":[["p2-55.webp",55],["p2-56.webp",56],["p2-57.webp",57],["p2-58.webp",58]]},"poem":{"t":"أُمّي","pg":59,"verses":[["وَتَصيحُ بي وَتَصيحُ تَسْألُني","عَنْ سِرِّ آلامي وَأنّاتي"],["فَعُيونُها في الهَمِّ تَرْمُقُني","وَبِظِلِّها تَعْرى حَماقاتي"],["قَدْ هاجَها ألَمي وَرَوَّعَها","حُزْني وَأشْلاءُ ابْتِساماتي"],["فَمَضَتْ تُهَدْهِدُني وَتَسْرِقُني","بِحَنانِها الظَّمْآنِ مِنْ ذاتي"],["وَتَرُدُّني وَلَداً وَتُرْجِعُني","طِفْلاً، أعاني مِنْ شَقاواتي"],["تَسْتَلْهِمُ الماضي، تُذَكِّرُني","أحْلى سُوَيْعاتي وأوْقاتي"],["أمّاهُ... يا ظِلّي وَمِرْآتي","أمّاهُ... يا أغْلى صَديقاتي"],["إِنّي أحِسُّ الكَوْنَ يَصْخَبُ لي","ضاقَت مَلاعِبُهُ بِغاياتي"],["فَتَرَفَّقي أمّاهُ، واصْطَبِري","سأظَلُّ أعْدو خَلْفَ زَلّاتي"],["سألُمُّها في قَبْضَتي وَطَناً","فَوُجودُها كُلُّ احْتِياجاتي"]],"voc":[["تَرْمُقُني","تُراقِبُني."],["تَعْرى","تَنْكَشِفُ."],["تُهَدْهِدُني","تُخَفِّفُ عَنّي."],["تَسْتَلْهِمُ","تَسْتَرْجِعُ."],["يَصْخَبُ","يَضِجُّ احْتِفالاً."],["زَلّاتي","أخطائي."]],"img":[["p2-59.webp",59]]},"grammar":{"t":"الفِعْلُ الماضي","pg":60,"pts":["الفعلُ الماضي مبنيٌّ دائمًا.","يُبنى على الفتح إذا لم يتّصل به شيء، أو اتّصلت به تاءُ التّأنيث السّاكنة أو ألفُ الاثنين (سهِرَ، سهِرَتْ، سهِرا).","يُبنى على الضّمّ إذا اتّصلت به واوُ الجماعة (سهِروا).","يُبنى على السّكون إذا اتّصل به ضميرُ رفعٍ متحرّك: التّاء، نا، نون النّسوة (سهِرْتُ، سهِرْنا، سهِرْنَ)."],"img":[["p2-60.webp",60],["p2-61.webp",61]],"q":[["«الأمّهاتُ سَهِرْنَ»: يُبنى الفعل على:",["السّكون","الفتح","الضّمّ","الكسر"],0,"اتّصلت به نون النّسوة."],["«الأبناءُ شكروا»: يُبنى الفعل على:",["الضّمّ","الفتح","السّكون","الكسر"],0,"واو الجماعة."],["«رَبَّتِ الأمُّ ابنَها»: يُبنى الفعل «ربّى» على:",["الفتح المقدّر","الضّمّ","السّكون","الكسر"],0,"آخره ألف."]]},"imla":{"t":"كِتابَةُ الأسْماءِ المَوْصولَةِ (٢)","pg":63,"pts":["تكملةُ كتابة الأسماء الموصولة ومثنّاها وجمعها."],"img":[["p2-63.webp",63]]},"khatt":{"t":"حرفا (ي، م)","pg":64,"pts":["حرفا (ي، م) بخطّ الرُّقعة."],"img":[["p2-64.webp",64]]},"taabir":{"t":"التَّعْبيرُ عَنْ صورَةٍ","pg":65,"pts":["التّعبيرُ عن صورة."],"img":[]}},"listen":"صَباحُكِ أحْلى"},{"id":"P2U6","part":2,"n":6,"sec":{"read":{"t":"النَّباتاتُ العِطْرِيَّةُ في فِلَسْطينَ","pg":67,"paras":["حَبا اللّهُ فِلَسْطينَ مَوْقِعاً جُغْرافيّاً مُتَمَيِّزاً؛ جَعَلَها مُلْتَقى المُؤَثِّراتِ البَحْرِيَّةِ والصَّحْراوِيَّةِ، حَيْثُ تَنَوَّعَتْ تَضاريسُها مِنْ جِبالٍ، وَسُهولٍ، وأوْدِيَةٍ، وأغْوارٍ، كَما وَهَبَها تَنَوُّعاً في المُناخِ والتُّرْبَةِ؛ كُلُّ هذِهِ العَوامِلِ جَعَلَتْ فِلَسْطينَ تَزْهو بِألوانٍ شَتّى مِنَ الزُّروعِ والنَّباتاتِ الَّتي فيها الجَمالُ والفائِدَةُ، وَمِنْها النَّباتاتُ العِطْرِيَّةُ.","تَنْتَشِرُ النَّباتاتُ البَرِّيَّةُ العِطْرِيَّةُ في الصَّحارى، والسُّهولِ، والوِدْيانِ، والجِبالِ، وَهِيَ النَّباتاتُ الّتي تَنْبُتُ دونَ تَدَخُّلِ الإِنْسانِ، وَلَها رائِحَةٌ عِطْرِيَّةٌ زَكِيَّةٌ، يَنْتَعِشُ الإِنْسانُ إِذا ما اشْتَمَّها مِنْ قَريبٍ أوْ بَعيدٍ.","وَلِهَذِهِ النَّباتاتِ أهَمِّيَّةٌ كَبيرَةٌ؛ فَهِيَ دَواءٌ وَغِذاءٌ لِلإِنْسانِ، تُسْتَخْرَجُ مِنْها الزُّيوتُ والرَّوائِحُ العِطْرِيَّةُ، وَمِنْ أشْهَرِ هذِهِ النَّباتاتِ في فِلَسْطينَ الزَّعْتَرُ، والميرَميَّةُ، والشّيحُ، وإكْليلُ الجَبَلِ، والبابونِج، والجِعْدَةُ...، وَلِكُلٍّ مِنْ هذِهِ النَّباتاتِ اسْتِخْداماتُهُ الغِذائِيَّةُ والطِّبِّيَّةُ. بَيْدَ أنَّ أشْهَرَ تِلْكَ النَّباتاتِ، وأكْثَرَها اسْتِعْمالاً في فِلَسْطينَ نَباتُ الزَّعْتَرِ الَّذي أطْلَقَ عَلَيْهِ بَعْضُ النّاسِ (ذَهَبَ فِلَسْطينَ الأخْضَرَ)، فَلا يَكادُ بَيْتٌ يَخْلو مِنْهُ.","ارْتَبَطَ الزَّعْتَرُ بِغِذاءِ الفِلَسْطينِيِّ التَّقْليدِيِّ، وَعِشْقِهِ الأبَدِيِّ لِلْأرْضِ -ِفي الغالِب- ًوالوَطَنِ، مَقْرونا بِزَيْتِ الزَّيْتونِ وَخَيْراتِهِ، وَهِيَ عَلاقةٌ أبْرَزَها أدَباءُ فِلَسْطينَ، فَمِنْهُمْ مَنْ قالَ:","أحِبُّ الزَّيْتَ والزَّيْتونَ والزَّعْتَرْ وَلكِنّي أحِبُّكَ مَوْطِني أكْثَرْ","فالزَّعْتَرُ إِذَنْ رَمْزٌ حاضِرٌ في الثَّقافَةِ والتّاريخِ الفِلَسْطينِيِّ، وَهُوَ يُمَثِّلُ حالَةَ صُمودٍ وَعِشْقٍ وَتَواصُلٍ مَعَ الأرْضِ يَوْمَ أنْ كانَ هذا النَّباتُ بَرِّيّاً، يَجْمَعُهُ النّاسُ مِنَ البَراري والجِبالِ، سَواءً لِأغْراضِ الأكْلِ، أوِ التِّجارَةِ، قَبْلَ أنْ يَبْدَأ الفِلَسْطينِيّون بِزِراعَتِهِ في مَزارِعِهِمْ في تِسْعينِيّاتِ القَرْنِ الماضي، ثُمَّ التَّوَسُّعِ في زِراعَتِهِ بِوَسائِلَ حَديثَةٍ؛ مَكَّنَتْ مِنْ مُضاعَفَةِ كَمِّيَّةِ الإِنْتاجِ، وَعَدَدِ القَطْفاتِ مِنْ ثَلاثٍ إِلى خَمْسِ مَرّاتٍ في العامِ.","يُساعِدُ الزَّعْتَرُ في عِلاجِ السُّعالِ الدّيكيّ، والالتِهاباتِ الشُّعْبِيَّةِ، والرَّبْوِ، وَيَعْمَلُ عَلى تَقْوِيَةِ الجِهازِ المَناعِيِّ والعَضَلاتِ، وَعَضَلَةِ القَلْبِ، وَهُوَ مُسَكِّنٌ لِلْآلامِ، وَمُطَهِّرٌ لِلدَّوْرَةِ الدَّمَوِيَّةِ، وَمُنَشِّطٌ لَها، وَيُعالِجُ التِهاباتِ المَسالِكِ البَوْلِيَّةِ، والمَثانَةِ، والتِهاباتِ الحَلْقِ والحَنْجَرَةِ، وَيُساعِدُ عَلى طَرْدِ الغازاتِ مِنَ المَعِدَةِ، وَهُوَ طارِدٌ لِلْفِطْرِيّاتِ والطُّفَيْلِيّاتِ، وَيَمْنَعُ تَصَلُّبَ الشَّرايينِ، وَجَفافَ العَيْنِ، وَإِصابَتَها بِالمِياهِ الزَّرْقاءِ، وَيُنْصَحُ بِإِعْطائِهِ لِلطَّلَبَةِ؛ لِأنَّه مُقَوٍّ لِلذّاكِرَةِ.","يُغْلى الزَّعْتَرُ مَعَ الماءِ، وَيُشْرَبُ كالشّايِ، وَيَتَناوَلُ المَريضُ كأساً واحِدَةً إِلى ثَلاثِ كُؤوسٍ مِنَ الزَّعْتَرِ في اليَوْمِ الواحِدِ، وَلِعِدَّةِ أيّامٍ، وَلَهُ فَوائِدُ يَقولُ فيها العَطّارونَ والمُهْتَمّونَ بِالطِّبِّ والوَصْفاتِ الشَّعْبِيَّةِ: إِنَّها صَيْدَلِيَّةٌ مُتَكامِلَةٌ.","أمامَ كُلِّ هذِهِ المُعْطَياتِ والحَقائِقِ، فإِنَّ الفِلَسْطينِيَّ مَدْعُوٌّ إِلى الحِفاظِ عَلى هذِهِ النَّباتاتِ في مَنابِتِها، وَتَكْثيرِها، وَحِمايَتِها مِنَ إِضافَةِ إِلى كُلِّ ما ذُكِر- الاعْتِداءِ الجائِرِ عَلَيْها؛ لِأنَّها بِالا تُشَكِّلُ إِحْدى -َ مُقَوِّماتِ التُّراثِ الفِلَسْطينِيِّ.","فائِدةٌ لُغَويَّة العَطّارون: مُفْردُها عَطّارٌ، وَهُوَ صاحِبُ مِهْنَةِ العِطارَةِ الَّتي تَهْتَمُّ بِالنّباتاتِ، والأعْشابِ، والتَّوابِلِ الطَّبيعِيَّةِ."],"voc":[["تَزْهو","تَفْخَرُ."],["شَتّى","جَمْعُ شَتيت، بِمَعْنى مُخْتَلِف."],["زَكِيَّة","ذات رائِحَةٍ عَطِرَةٍ."],["الجائِرُ","الظّالِمُ."],["مُقَوِّماتُ","مُكَوِّناتُ، مُفْرَدُها مُقَوِّمَة."]],"img":[["p2-67.webp",67],["p2-68.webp",68],["p2-69.webp",69],["p2-70.webp",70]]},"poem":{"t":"بيسانُ","pg":71,"verses":[["أما زالَ في عَيْنَيْكِ صَيْفٌ وأنْجُمٌ","وَفي سَهْلِكِ الرَّيّانِ مِسْكٌ وَعَنْدَمُ؟"],["أما زالَ بَيْنَ الضِّفَّتَيْنِ زَنابِقٌ","تُهَدْهِدُ شَوْقَ الغَوْرِ، والغَوْرُ يَنْسِمُ؟"],["خُذيني، لَقَدْ أشْعَلْتُ كُلَّ مَراكِبي","إِلى غابَةِ الدِّفْلى أضيعُ وأرْسُمُ"],["وأنْقُشُ أشْعاري عَلى خَصْرِ تينَةٍ","وَتَحْتَ ظِلالِ الزَّيْزَفونِ أخَيِّمُ"],["بِنَفْسِيَ أنْفاسُ البَساتينِ تَغْتَفي","بِنَفْسِيَ حَسّونُ الجَليلِ المُنَمْنَمُ"],["حَنانَيْكَ يا نَهْرَ الشَّريعَةِ رُدَّني","إِلى صَدْرِها الحاني أشُمُّ وألْثُمُ"],["عَلى جَنَباتِ النَّهْرِ فاضَتْ حُشاشَتي","وَعِنْدَ مَصَبِّ النَّهْرِ روحي تُحَوِّمُ"],["إِذا خانَني بَوْحي فَكُلُّ جَوارِحي","تُرَدِّدُ يا بيسانُ إِنّي مُتَيَّمُ"],["لِغَيْرِ هَواها لا يَطيبُ ليَ الهَوى","بِغَيْرِ ثَراها لا يَطيبُ التَّيَمُّمُ"],["فِراقُكِ مأساتي، وَوَصْلُكِ جَنَّتي","حَياتي بِلا عَيْنَيْكِ تِلْكَ جَهَنَّمُ"],["إِذا لَمْ أخَضِّبْ وَجْنَتَيْكِ ثَلاثَةً","عَلَيَّ شَميمُ البُرْتُقالِ مُحَرَّمُ"]],"voc":[["عَنْدَمُ","نَباتٌ يُصْبَغُ بِهِ."],["تُهَدْهِدُ","تُلَطِّفُ."],["الدِّفْلى","شَجَرٌ أخْضَرُ حَسَنُ المَنْظَرِ يَكونُ في الأوْدِيَةِ."],["الزَّيْزَفونِ","شَجَرٌ حَرَجيٌّ لَهُ زَهْرٌ أبْيَضُ، ذو رائِحَةٍ عَطِرَةٍ."],["المُنَمْنَمُ","المُزَخْرَفُ. المُرَقَّشُ."],["حَنانَيْكَ","رَحْمَةً لَكَ."],["حُشاشَتي","بَقِيَّةُ الرّوحِ في المُحْتَضِرِ."],["أخَضِّبُ","أصْبُغُ بِالحِنّاءِ."]],"img":[["p2-71.webp",71],["p2-72.webp",72]]},"grammar":{"t":"الفِعْلُ المُضارِعُ","pg":73,"pts":["يُرفع المضارع إذا لم يُسبق بناصب أو جازم، وعلامته الضّمّة.","يُنصب إذا سُبق بأحد أحرف النّصب (أنْ، لنْ، كي، لام التّعليل)، وعلامته الفتحة.","يُجزم إذا سُبق بأحد أحرف الجزم (لم، لا النّاهية، لام الأمر)، وعلامته السّكون."],"img":[["p2-73.webp",73],["p2-74.webp",74]],"q":[["«جئتُ كي أتعلّمَ»: الفعل «أتعلّم»:",["منصوب","مرفوع","مجزوم","مبنيّ"],0,"سُبق بـ«كي»."],["«لا تقطفْ الأزهار»: الفعل «تقطفْ»:",["مجزوم بلا النّاهية","مرفوع","منصوب","مبنيّ"],0,""],["«تفوحُ رائحةُ الزّعتر»: علامة رفع «تفوح»:",["الضّمّة","الفتحة","السّكون","الواو"],0,""]]},"imla":{"t":"إِمْلاءٌ اخْتِبارِيٌّ","pg":76,"pts":["إملاءٌ اختباريّ."],"img":[["p2-76.webp",76]]},"khatt":{"t":"حرفا (ح، ش)","pg":77,"pts":["حرفا (ح، ش) بخطّ الرُّقعة."],"img":[["p2-77.webp",77]]},"taabir":{"t":"وَصْفُ الطَّبيعَةِ","pg":77,"pts":["وصفُ الطّبيعة."],"img":[["p2-77.webp",77]]}},"listen":"الطِّبُّ العَرَبِيُّ"},{"id":"P2U7","part":2,"n":7,"sec":{"read":{"t":"حادِثٌ عَلى الطَّريقِ","pg":79,"paras":["حَمَلَتْ سَيّارَةُ الإِسْعافِ أيْمَنَ، وانْطَلَقَتْ بِهِ إِلى مَشْفى في المَدينَةِ، بَيْنَما ذَهَبَ أحْمَدُ وَرامي لِإِبْلاغِ والديْهِ بِما حَدَثَ. وَفي المَشْفى، تَبَيَّنَ أنَّ ساقَهُ قَدْ كُسِرَتْ؛ نَتيجَةَ اصْطِدامِ السَّيّارَةِ بِهِ عِنْدَ عُبورِهِ الشّارِعَ، بَعيداً عَنْ خَطِّ المُشاةِ.","وَفي المَشْفى، اقْتَرَبَ والِدُ أيْمَنَ مِنَ السّائِقِ قائِلاً: لا تَقْلَقْ، الحَمْدُ للّهِ، \"قَدَّرَ، وَلَطَفَ\".","- السّائِقُ: شُكراً يا عَمّي، وأتَمَنّى الشِّفاءَ العاجِلَ لِأيْمَنَ.","وَفِي اليَوْمِ التّالي، كانَ الحادِثُ المَوْضوعَ الذي يَدورُ عَلى الألْسِنَة في المَدْرَسَةِ، فَقَدْ قالَ المُعَلِّمُ باسِمٌ: إِنَّ ما حَدَثَ بِالأمْسِ يَجِبُ أنْ يَكونَ دَرْساً يَتَعَلَّمُ مِنْهُ الجَميعُ.","فيما قالَ المُعَلِّمُ وَليدٌ: يَجِبُ أنْ نَجِدَ حَلّاً؛ إِذ إِنَّ الأمْرَ لَنْ يَتَوَقَّفَ عِنْدَ هذا الحَدِّ، وَهذا ما أكَّدَهُ مُديرُ المَدْرَسَةِ بِقَوْلِهِ: هذا صَحيحٌ، وَمِنَ الواجِبِ أنْ يَقومَ وَفْدٌ مِنَ المَدْرَسَةِ بِزِيارَةِ أيْمَنَ؛ لِلاطْمِئْنانِ عَلَيْهِ، وأنا بِدَوْري سَوْفَ أخاطِبُ الجِهاتِ المُخْتَصَّةَ؛ لِتَقْديمِ مُحاضَراتٍ؛ لِتَوْعِيَةِ الطَّلَبَةِ وأوْلِياءِ أمورِهِمْ وَالسّائِقينَ بِضَرورَةِ الالتِزامِ بِقَوانينِ السَّيْرِ.","بَعْدَ أسْبوعٍ، قُدِّمَتْ مُحاضَرَةٌ إِرْشادِيَّةٌ لِلطَّلَبَةِ والأهالي حَوْلَ اسْتِخْدامِ حِزامِ الأمانِ، وَعُبورِ الشَّارِعِ مِنْ خَطِّ المُشاةِ، والتَّعامُلِ مَعَ إِشاراتِ المُرورِ، وَضَرورَةِ التَّأنّي أثْناءَ القِيادَةِ، والابْتِعادِ عَنِ السُّرْعَةِ الزّائِدِةِ، ما مِنْ شأنِهِ أنْ يَحِدَّ مِن الحَوادِثِ المُرورِيَّةِ الَّتي توقِعُ كَثيراً مِنَ الضَّحايا؛ جَرّاءَ مُخالَفَةِ هذِهِ القَوانينِ.","وَفيما كانَ الحُضورُ يَسْتَمِعونَ إِلى المُحاضِرِ، كانَتِ المُفاجأةُ...! لَقَدْ دَخَلَ أيْمَنُ القاعَةَ مُتَّكِئاً عَلى عُكّازٍ، وَمُسْتَنِداً إِلى السّائِقِ الَّذي أصابَهُ بِسَيّارَتِهِ، بَيْنَما كانَ أهْلُهُ يَسيرونَ خَلْفَهُما، الأمْرُ الَّذي دَعا المُحاضِرَ إِلى التَّوَقُّفِ عَنْ حَديثِهِ؛ لِيُشارِكَ الجُمْهورَ تَصْفيقَهُمُ الطَّويلَ.","وَفي نِهايَةِ المُحاضَرَةِ، وَقَفَ أيْمَنُ وَقالَ:\"الالتِزامُ بِقَوانينِ السَّيرِ يَضْمَنُ الأمانَ، وَيَحْفَظُ حَياةَ الإِنْسانِ\"."],"voc":[["رُوَيْداً","مَهْلاً."]],"img":[["p2-79.webp",79],["p2-80.webp",80],["p2-81.webp",81],["p2-82.webp",82]]},"grammar":{"t":"فِعْلُ الأمْرِ","pg":83,"pts":["فعلُ الأمر مبنيٌّ دائمًا.","يُبنى على السّكون إذا كان صحيحَ الآخر ولم يتّصل به شيء (احذَرْ).","يُبنى على حذف حرف العلّة إذا كان معتلَّ الآخر (امشِ، ادعُ، اسعَ).","يُبنى على حذف النّون إذا اتّصلت به ألفُ الاثنين أو واوُ الجماعة أو ياءُ المخاطبة (احذرا، احذروا، احذري)."],"img":[["p2-83.webp",83],["p2-84.webp",84]],"q":[["«انتبهوا للطّريق»: يُبنى الفعل على:",["حذف النّون","السّكون","حذف حرف العلّة","الفتح"],0,""],["«امشِ على الرّصيف»: يُبنى الفعل على:",["حذف حرف العلّة","السّكون","حذف النّون","الضّمّ"],0,""],["«قِفْ عند الإشارة»: يُبنى على:",["السّكون","حذف النّون","الفتح","الكسر"],0,""]]},"imla":{"t":"عَلامَتا التَّرْقيمِ: الفاصِلَةُ، وَالنُّقْطَةُ","pg":85,"pts":["الفاصلة (،): بين الجمل المتّصلة المعنى، وبعد المنادى، وبين المعطوفات.","النّقطة (.): في نهاية الجملة التّامّة المعنى."],"img":[["p2-85.webp",85]]},"khatt":{"t":"حرف (ن)","pg":86,"pts":["حرف (ن) بخطّ الرُّقعة."],"img":[["p2-86.webp",86]]},"taabir":{"t":"كِتابَةُ قِصَّةٍ","pg":87,"pts":["كتابةُ قصّة."],"img":[]}},"listen":"مُسْتَقْبَلُ صِناعَةِ السَّيّاراتِ"},{"id":"P2U8","part":2,"n":8,"sec":{"read":{"t":"مَدينَةُ القَيْرَوانِ رابِعَةُ الثَّلاثِ","pg":89,"paras":["إِحْدى دُرَرِ التّاريخِ الإِسْلامِيِّ، هِيَ تِلْكَ المَدينَةُ الأخّاذَةُ الوَدودُ الغَنِيَّةُ بِالذِّكْرَياتِ التّاريخِيَّةِ، والمَعالِمِ المُتَمَيِّزَةِ، وَمَدينَةُ الجَمالِ الخالِدِ الَّذي ألْهَمَ عَدَداً مِنَ الفَنّانينَ فَنَّهُم الرّاقي، بِما تَمْلِكُهُ مِنْ سِحْرٍ خاصٍّ صَنَعَتْهُ أزِقَّتُها المُلْتَوِيَةُ، وَمَمَرّاتُها وَقِبابُها ذاتُ اللَّوْنِ الأبْيَضِ الَّتي تَحْتَضِنُ مَسْجِدَ عُقْبَةَ بْنِ نافِعٍ، القائِدِ الَّذي أسَّسَ تِلْكَ المَدينَةَ بَعيداً عَنِ العُمْرانِ؛ لِتَكونَ آمِنَةً مِنْ هُجومِ الأعْداءِ، وَمُنْطَلَقاً لِجُيوشِهِ الفاتِحَةِ للشَّمالِ الإِفْريقِيِّ، وَحَوْلَ أحْيائِها تَحومُ الأسْوارُ بِقِلاعِها؛ لِتُعْطيَ هذهِ المَدينَةَ صورَةً مِنْ خارِجِ الزَّمَنِ الحاضِرِ.","إِنَّها مَدينَةُ القَيْرَوانِ التّونِسِيَّةُ الَّتي أطْلِقَ عَلَيْها (رابِعَةُ الثَّلاثِ) بَعْدَ مَكَّةَ المُكَرَّمَةِ، والمَدينَةِ المُنَوَّرَةِ، والقُدْسِ، في دَلالَةٍ واضِحَةٍ عَلى مَكانَتِها الدّينِيَّةِ، وَهيَ تَقَعُ على بُعْدِ مِئَةٍ وَسِتّينَ كيلو مِتْراً جَنوبَ العاصِمَةِ تونِسَ.","أنْشِئَتْ في القَيْرَوانِ المَكْتَباتُ العامَّةُ، والمَكْتَباتُ المُلْحَقَةُ بِالجَوامِعِ والمَدارسِ، وَكانَتْ هذهِ المَكْتَباتُ مَفْتوحَةً أمامَ الدّارِسينَ، تَضُمُّ نَفائِسَ الكُتُبِ، وَمِنْ أشْهَرِ هذهِ المَكْتَباتِ (بَيْتُ الحِكْمَةِ) الَّذي أنْشأهُ الأميرُ إِبْراهيمُ الثّاني الأغْلَبيُّ؛ مُحاكاةً لِبَيْتِ الحِكْمَةِ الَّذي أسَّسَهُ هارونُ الرَّشيد في بَغْدادَ، حَيْثُ كانَتْ هذهِ المَكْتَبَةُ نَواةً لِمَدْرَسَةِ الطِّبِّ القَيْرَوانِيَّةِ. كَما كانَ لَها دَوْرٌ عَظيمٌ في إِثْراءِ الحَرَكَةِ العِلْمِيَّةِ في بِلادِ إِضافَةِ إِلى ذلِك- ْالمَغْرِبِ لِزَمَنٍ طَويلٍ؛ إِذْ كانَتبِالا مَعْهَداً عِلْمِيّاً -َ لِلدَّرْسِ والبَحْثِ العِلْمِيِّ، والتَّرْجمَةِ مِنَ اللُّغاتِ اللّاتينِيَّةِ، وَمَركزاً لِنَسْخِ المُصَنَّفاتِ، وَكانَ يَتَولّى الإِشْرافَ عَلَيْها حَفَظَةٌ مَهَمَّتُهُمُ السَّهَرُ عَلى حِراسَةِ ما تَحْتَويهِ مِنْ كُتُبٍ، وَتَزْويدُ طَلَبَةِ العِلْمِ الَّذينَ يَرْتادونَها بِما يَلْزَمُهُمْ مِنْ هذِهِ الكُتُبِ، وَيَرْأسُ هؤلاءِ الحَفَظَةَ ناظِرٌ كانَ يُعْرَفُ بِصاحِبِ بَيْتِ الحِكْمَةِ.","كانَ إِنْشاءُ مَدينَةِ القَيْرَوانِ بِمَثابَةِ بِدايةٍ لِتاريخِ الحَضارَةِ العَرَبِيَّةِ الإِسْلامِيَّةِ في المَغْرِبِ العَرَبِيِّ، فَقَدْ كانَتِ المَدينَةُ تَلْعَبُ دَوْرَيْنِ مُهِمَّيْنِ في آنٍ واحِدٍ، هُما: الجِهادُ، والدَّعْوَةُ. فبَيْنَما كانَتِ الجُيوشُ تَخْرُجُ مِنْها لِلْغَزْوِ والفَتْحِ، كانَ الفُقَهاءُ يَخْرُجونَ مِنْها؛ لِيَنْتَشِروا في البِلادِ يُعَلِّمونَ العَرَبِيَّةَ، وَيَنْشُرونَ الإِسْلامَ.","تَمْتَلِكُ القَيْرَوانُ سِحْرَ المَدينَةِ العَتيقَةِ، َسِحْرَ مَدينَةٍ يَتَعانَقُ فيها الوَرَعُ والتُّراثُ، فَفي أسْواقِها يَكْتَشِفُ الزّائِرُ أكْثَرَ مِنْ كَنْزٍ، فَهذا دُكّانٌ يَعْرِضُ المَرْقومَ بِألْوانِهِ العَديدَةِ، وَذاكَ دُكّانٌ يَخْتَصُّ بِصِناعَةِ الأحْذِيَةِ التَّقْليدِيَّةِ، والسُّروجِ المُطَرَّزَةِ، وإلى جانِبِهِ دُكّانٌ يَخْتَصُّ بِصِناعَةِ الخَزَفِ والأدَواتِ النُّحاسِيَّةِ، وَهُناكَ الحِرْفِيّونَ يُباشِرونَ أعْمالَهُم، وَخُصوصاً صِناعَة الزَّرابِيِّ القَيْرَوانِيَّةِ المَشْهورَة بِألْوانِها، وأشْكالِها، وَجَوْدَةِ صِناعَتِها، وَلا يُمْكِنُ زِيارَةُ القَيْرَوانِ دونَ تَذَوُّقِ حَلَوِيّاتِها الشَّهيرَةِ، وأشْهَرُها (المَقْروضُ) المَحْشُوُّ بِالتَّمْرِ، أوِ اللَّوْزِ.","عِنْدَما تُذْكَرُ مَدينَةُ القَيْرَوانِ يُذْكَرُ اسْمُ بانيها القائِدِ العَرَبِيِّ عُقْبَةَ ابنِ نافِعٍ، وَقَوْلَتُهُ المَشْهورَةُ الَّتي قالَها عِنْدَما بَلَغَ في فُتوحاتِهِ المُحيطَ الأطْلَسِيَّ، وَهُوَ يَرْفَعُ يَدَهُ إِلى السَّماءِ، وَيَصْرُخُ بِأعْلى صَوْتِهِ:\"اللّهُمَّ اشْهَدْ أنّي بَلَغْتُ المَجْهودَ، وَلَوْلا هذا البَحْرُ لَمَضَيْتُ في بِلادِ اللّهِ أقاتِلُ مَنْ كَفَرَ بِكَ؛ حَتّى لا يُعْبَدَ أحَدٌ دونَكَ\"."],"voc":[["ألْهَمَ","أوْحى إِلى."],["تَحومُ","تُحيطُ."],["النَفائِسَ","القَيِّمَةَ."],["إِثْراءِ","تَطْويرِ."],["الوَرَعِ","التَّقْوى."],["المَرْقومَ","المُطَرَّزَ، أو المَكتوبَ."],["الزَّرابِيِّ","مُفْرَدُها الزُّرْبِيَةُ، وَهِيَ البُسُطِ."],["المَقْروضُ","نَوْعٌ مِنَ الحَلَوِيّاتِ."]],"img":[["p2-89.webp",89],["p2-90.webp",90],["p2-91.webp",91],["p2-92.webp",92]]},"poem":{"t":"حَنينٌ إِلى القَيْرَوانِ","pg":93,"verses":[["مَوْتُ الكِرامِ حَياةٌ في مَواطِنِهِمْ","فإنْ هُمُ اغْتَرَبوا ماتوا وَما ماتوا"],["يا أهْلَ وُدِّيَ لا واللّهِ ما نُقِضَتُ","عِنْدي عُهودٌ وَلا ضاقَتْ مَوَدّاتُ"],["لَئِنْ بَعُدْتُمْ وَحالَ البَحْرُ دونَكُمُ","لَبَيْنَ أرْواحِنا في النَّوْمِ زَوْراتُ"],["ما نِمْتُ إِلّا لِكَيْ ألقى خيالَكُم","وأيْنَ مِنْ نازِحِ الأوْطانِ نَوْماتُ"],["ماذا عَلى الرّيحِ لَوْ أهْدَتْ تَحِيَّتَها","إِلَيْكُمُ مِثلَ ما تُهْدى التَّحِيّاتُ؟"],["أصْبَحْتُ في غُرْبَتي لَوْلا مُكاتَمَتي","بَكَتْنِيَ الأرْضُ فيها والسَّماواتُ"],["كأنَّني لَمْ أذُقْ بِالقَيْرَوانِ جَنًى","وَلَمْ أقُلْ ها لِأحْبابي وَلا هاتوا"],["أبَعْدَ أيّامِنا البيضِ الَّتي سَلَفَت","تَروقُني غَدَواتٌ أوْ عَشِيّاتُ"],["هَلْ مِنْ رِسالَةِ حُبٍّ أسْتَعينُ بِها","عَلى سَقامي فَقَدْ تَشْفي الرِّسالاتُ"],["ألا سَقى اللّهُ أرْضَ القَيْرَوانِ حَيا","كأنّهُ عَبَراتي المُسْتَهِلّاتُ"],["فإِنَّها لِدَةُ الجَنّاتِ، تُرْبَتُها","مِسْكِيَّةٌ، وَحَصاها جَوْهَرِيّاتُ"]],"voc":[["نُقِضَتْ","نُكِثَتْ."],["حالَ","مَنَعَ."],["زَوْرات","مفرَدُها زَوْرَةٌ، وهي الزِّيارَةُ."],["مُكاتَمَتي","تَظاهُري بالكِتْمانِ."],["جَنًى","ثِماراً."],["ها","خُذْ."],["سَقامي","مَرَضي الشَّديدِ."],["حَياً","المَطَرَ الشَّديدَ."],["المُسْتَهِلّاتُ","الغَزيراتُ."],["لِدَةُ","مُشابِهَةُ."]],"img":[["p2-93.webp",93],["p2-94.webp",94]]},"grammar":{"t":"الفاعِلُ","pg":95,"pts":["الفاعل: اسمٌ مرفوعٌ يدلّ على من قام بالفعل، وهو أحد ركني الجملة الفعليّة.","من صور الفاعل: الاسم الظّاهر (المفرد والمثنّى وجمع التّكسير وجمعا السّلامة)، والضّمير المتّصل.","علامات رفعه: الضّمّة، والألف للمثنّى، والواو لجمع المذكّر السّالم والأسماء الخمسة."],"img":[["p2-95.webp",95],["p2-96.webp",96]],"q":[["الفاعلُ في «بنى عقبةُ مدينةَ القيروان»:",["عقبةُ","بنى","مدينةَ","القيروان"],0,""],["«ازدهرتِ الحضارتان»: علامة رفع الفاعل:",["الألف","الضّمّة","الواو","الياء"],0,""],["الفاعل في «فتحْنا البلاد»:",["نا (ضمير متّصل)","البلاد","فتح","لا فاعل"],0,""]]},"imla":{"t":"عَلاماتُ التَّرْقيمِ: الاسْتِفْهامُ، وَالتَّعَجُّبُ","pg":98,"pts":["علامةُ الاستفهام (؟) بعد الجملة الاستفهاميّة.","علامةُ التّعجّب (!) بعد جمل التّعجّب والانفعال."],"img":[["p2-98.webp",98]]},"khatt":{"t":"حرفا (س، ق)","pg":100,"pts":["حرفا (س، ق) بخطّ الرُّقعة."],"img":[["p2-100.webp",100]]},"taabir":{"t":"التَّحَدُّثُ بِلِسانِ الآخَرينَ","pg":101,"pts":["التّحدّثُ بلسان الآخرين."],"img":[]}},"listen":"جَزيرَةُ صِقِلِّيَةَ شاهِدٌ عَلى الحَضارَةِ العَرَبِيَّةِ"},{"id":"P2U9","part":2,"n":9,"sec":{"read":{"t":"البَخيلُ","pg":103,"paras":["عاشَ رَجُلٌ بَخيلٌ في قَرْيَةٍ نائِيَةٍ، كانَ مَعْروفاً بَيْنَ أهْلِ قَرْيَتِهِ بِهذِهِ الصِّفَةِ، عَلى الرَّغْمِ مِنْ أنَّهُ وَرِثَ عَنْ أبيهِ ثَرْوَةً هائِلَةً، وَقَدْ بَلَغَ مِنْ شِدَّةِ بُخْلِهِ، أنَّهُ كانَ إِذا أرادَ أنْ يَذْهَبَ إِلى المَدينَةِ لِأمْرٍ ضَرورِيٍّ، يَقِفُ عَلى الشّارِعِ المُؤَدّي إِلَيْها وَقْتاً طَويلاً، لَعَلَّ أحَدَ مَعارِفِهِ أوْ أصْدِقائِهِ مِمَّنْ يَقْصِدونَ الذَّهابَ إِلَيْها يَمُرُّ بِمَرْكِبَتِهِ الخاصَّةِ، فَيأخُذُهُ مَعَهُ، وَيُريحُهُ مِنْ دَفْعِ أجْرَةِ الطَّريقِ، بَلْ لَقَدْ عُرِفَ عَنْهُ أنَّهُ عَزَفَ عَنِ الزَّواجِ؛ حَتّى لا يَضْطرَّ لِدَفْعِ تَكاليفِهِ.","كانَ دائِمَ التَّفْكيرِ في الحِرْصِ عَلى أمْوالِهِ الَّتي يَحْتَفِظُ بِها في مَكانٍ ما في بَيْتِهِ، بِحَيْثُ إِنَّهُ لَمْ يَكُنْ يُخالِطُ أهْلَ قَرْيَتِهِ إِلّا نادِراً؛ خَوْفاً مِنْ أنْ تَنْزَلِقَ مِنْهُ كَلِمَةٌ، أوْ تَبْدُرَ مِنْهُ إِشارَةٌ قَدْ تَكْشِفُ عَنْ مَكانِ هذهِ الأمْوالِ. وَلِشِدَّةِ قَلَقِهِ وَخَوْفِهِ عَلَيْها مِنَ السَّرِقَةِ، قادَهُ تَفْكيرُهُ إِلى طَريقَةٍ يأمَنُ بِها وُصولَ النّاسِ إِلَيْها... لَقَدْ قَرَّرَ أنْ يَدْفِنَها في الأرْضِ الَّتي يَمْلِكُها، وَهكَذا فَعَلَ.","أصْبَحَ يَعودُ إِلى المَوْضِعِ الَّذي دَفَنَ فيهِ مالَهُ كُلَّ يَوْمٍ؛ لِيُلْقيَ نَظْرَةً عَلَيْهِ، وَيُحصيَهُ قِطْعَةً قِطْعَةً. وَذاتَ يَوْمٍ، رآهُ أحَدُ الأشْخاصِ هُناكَ، وَأخَذَ يُراقِبُهُ، فَعَرَفَ أنَّ الرَّجُلَ يُخْفي في باطِنِ الأرْضِ شَيئاً، وَفي اللَّيلَةِ التّالِيَةِ، ذَهَبَ إِلى المَكانِ نَفْسِهِ، وَحَفَرَ في الأرْضِ بِهُدوءٍ، وأخْرَجَ المالَ، وَلاذَ بِالفِرارِ.",".ِ.اكتَشَفَ الرَّجُلُ خَسارَتَهُ الفادِحَةَ، فَغَرِقَ في الحُزْنِ واليأس. راحَ يَئنُّ، وَيَتأوَّهُ، وَيَصْرُخُ.","رآهُ أحَدُ جيرانِهِ، فَسألَهُ عمّا حَدَثَ لَهُ، فَقالَ: لَقَدْ جَنى عَليَّ حُمْقي جِنايَةً ذَهَبَتْ بِمالي. فَسألَهُ جارُهُ: وَكَيْفَ؟ فأخْبَرَهُ بِما فَعَلَ، وَقالَ لَهُ ساخِراً: لا تَحْزَنْ إِلى هذا الحَدِّ، ادْفِنْ بَعْضَ الحِجارَةِ في الحُفْرَةِ، وَتَخيَّلْ أنَّها أمْوالُكَ، وَسَتَكْتَشِفُ أنَّ أمْوالَكَ تِلكَ تُشْبِهُ هذهِ الحِجارَةَ."],"voc":[["نائِيَةٍ","بَعيدَةٍ."],["لاذَ بِالفِرارِ","هَرَبَ."],["الفادِحَةُ","الكَبيرَةُ."],["يَتأوَّهُ","يَتَوَجَّعُ."]],"img":[["p2-103.webp",103],["p2-104.webp",104],["p2-105.webp",105],["p2-106.webp",106]]},"poem":{"t":"طَبيعَةٌ بَشَرِيَّةٌ","pg":107,"verses":[["مُحْسِنٌ أبْصَرَ يَوْماً طِفْلَةً","دَمْعَتاها هَمَتا رَقْراقَتَيْنْ"],["جَلَسَتْ تَبْكي بِقَلْبٍ موجَعٍ","تُرْسِلُ الآهَةَ حيناً آهَتَيْنْ"],["قالَ: ما الخَطْبُ؟ أجيبي طِفْلَتي","فَلِعَيْنَيْكِ فِداءٌ كُلُّ عَيْنْ"],["فأجابَتْ في نَحيبٍ مُحْزِنٍ","وَدُموعُ العَيْنِ تَسْقي الوَجْنَتَيْنْ"],["دِرْهَمي ضاعَ وَما لي غَيْرُهُ","وأنا مِنْ بَعْدِهِ صِفْرُ اليَدَيْنْ"],["قالَ: هَيّا طِفْلَتي لا تَجْزَعي","لا تُراعي، إِنَّ هذا الخَطْبَ هَيْنْ"],["وَحَباها دِرْهَماً في يَدِها","ماسِحاً مِنْ كُلِّ عَيْنٍ دَمْعَتَيْنْ"],["قال: هيّا أطْلِقي وَجْهَ الرِّضا","وَأريني بَسْمَةً أوْ بَسْمَتَيْنْ"],["غَيْرَ أنَّ الطِّفْلَةَ ازْدادَتْ بُكا","وَكأنَّ الكَرْبَ أضْحى كُرْبَتَيْنْ"],["فأجابَتْهُ بِقَلْبٍ مُوجَعٍ","لَمْ يُصِبْ إِحْداهُما أو الاثْنَتَيْنْ"],["إِنَّني أبْكي بِحُزْنٍ دِرْهَمي","فَهوَ لَوْ ظَّلَ لَأضْحى دِرْهَمَيْنْ"]],"voc":[["هَمَتا","سالَتا."],["رَقْراقَتَيْنْ","غَزيرَتَيْنِ."],["الخَطْبُ","المُصيبَةُ، أو الأمر."],["نَحيبٍ","بُكاءٍ شَديدٍ."],["الوَجْنَتَيْنْ","الخَدَّيْنِ."],["لا تَجْزَعي","لا تَحْزَني ."],["لا تُراعي","لا تَخافي ."],["هَيْنْ","سَهْل، وأصلها هَيِّن."],["حَباها","أعْطاها."],["الكَرْبَ","الحُزْنَ، والغَمَّ."]],"img":[["p2-107.webp",107],["p2-108.webp",108]]},"grammar":{"t":"المَفْعولُ بِهِ","pg":109,"pts":["المفعولُ به: اسمٌ منصوبٌ يدلّ على من وقع عليه الفعل.","من صوره: الاسم الظّاهر، والضّمير المتّصل (الهاء، الكاف، الياء، نا).","علامات نصبه: الفتحة، والياء للمثنّى وجمع المذكّر السّالم، والكسرة لجمع المؤنّث السّالم، والألف للأسماء الخمسة."],"img":[["p2-109.webp",109],["p2-110.webp",110]],"q":[["المفعول به في «أبصرَ المحسنُ طفلةً»:",["طفلةً","المحسنُ","أبصر","لا مفعول"],0,""],["«ساعدَ المحسنُ المحتاجين»: علامة نصب المفعول:",["الياء","الفتحة","الكسرة","الألف"],0,""],["«كافأتِ المعلّمةُ الطّالباتِ»: علامة النّصب:",["الكسرة","الفتحة","الياء","الضّمّة"],0,""]]},"imla":{"t":"إِمْلاءٌ اخْتِبارِيٌّ","pg":111,"pts":["إملاءٌ اختباريّ."],"img":[["p2-111.webp",111]]},"khatt":{"t":"حرفا (ع، و)","pg":112,"pts":["حرفا (ع، و) بخطّ الرُّقعة."],"img":[["p2-112.webp",112]]},"taabir":{"t":"تَحْويلُ قَصيدَةٍ إِلى حِوارٍ","pg":113,"pts":["تحويلُ قصيدةٍ إلى حوار."],"img":[]}},"listen":"مَنْ أنا؟"},{"id":"P2U10","part":2,"n":10,"sec":{"read":{"t":"طَرائِفُ عَرَبِيَّةٌ","pg":115,"paras":["بَيْنَما كانَ قَوْمٌ يأكُلونَ سَمَكاً عِنْدَ رَجُلٍ ثَرِيٍّ، طَرَقَ عَلَيْهِمُ أشْعَبُ البابَ مُسْتَأْذِناً، فَقالَ أحَدُهُمْ: خُذوا الأسْماكَ الكَبيرَةَ، واجْعَلوها في قَصْعَةٍ؛ حَتّى لا يأكُلَها أشْعَبُ، فَفَعَلوا ذلِكَ، ثُمَّ أذِنوا لَهُ بِالدُّخولِ، وَقالوا لَهُ: ما رَأْيُكَ في السَّمَكِ؟ فَقالَ: وَاللّهِ، إِنّي لأبْغِضُهُ بُغْضاً شَديداً؛ لِأنَّ أبي ماتَ في البَحْرِ، وأكَلَهُ السَّمَكُ. فَقالوا: إِذاً هَيّا لِلْأخْذِ بِثَأْرِ أبيكَ.","جَلَسَ أشْعَبُ إِلى المائِدَةِ، وَمَدَّ يَدَهُ إِلى سَمَكَةٍ صَغيرَةٍ مِنَ الَّتي أبْقَوْها بَعْدَ إِخْفاءِ الأسْماكِ الكَبيرَةِ، ثُمَّ وَضَعَها عِنْدَ أذُنِهِ، وَراحَ يَنْظُرُ إِلى القَصْعَةِ الَّتي فيها الأسْماكُ الكَبيرَةُ، ثُمَّ قالَ: أتَدْرونَ ما تَقولُ هذِهِ السَّمَكَةُ؟ إِنَّها تَقولُ: إِنّي صَغيرَةٌ لَمْ أحْضُرْ مَوْتَ أبيكَ، وَلَمْ أشارِكْ في التِهامِهِ، ثُمَّ قالَتْ: عَلَيْكَ بِتِلْكَ الأسْماكِ الَّتي في القَصْعَةِ، فَهِيَ الَّتي أدْرَكَتْ أباكَ، وَأكَلَتْهُ، فإِنَّ ثَأرَكَ عِنْدَها.","أعْطى أحَدُ الأدَباءِ خُفَّهُ إِلى إِسْكافٍ؛ لِيُصْلِحَهُ، فأهْمَلَهُ الإِسْكافُ مُدَّةً طَويلَةً، وَكانَ صاحِبُهُ يَمُرُّ بِهِ كُلَّ يَوْمٍ؛ لِيأخُذَ خُفَّهُ، فإِذا رآهُ الإِسْكافُ قادِماً مِنْ بَعيدٍ؛ أخَذَ الخُفَّ، وَغَمَسَهُ في الماءِ؛ لِيُوْهِمَ الرَّجُلَ أنَّهُ يَقومُ بِإِصْلاحِهِ، فَقالَ لَهُ الأديبُ ذاتَ يَوْمٍ: إِنّي أعْطَيْتُكَ الخُفَّ لِتُصْلِحَهُ، لا لِتُعَلِّمَهُ السِّباحَةَ!!!","اسْتَعارَ جُحا يَوْماً قِدْراً مِنْ أحَدِ جيرانِهِ، وَعِنْدَما أرْجَعَها أعادَ مَعَها قِدْراً أخْرى صَغيرَةً، فَسألَهُ جارُهُ عَنْ سَبَبِ إِرْفاقِ تِلْكَ القِدْرِ الصَّغيرَةِ مَعْ تِلْكَ الَّتي اسْتَعارَها، فَقالَ جُحا: إنَّ قِدْرَكَ وَلَدَتْ في الأمْسِ قِدْراً صَغيرَةً، وَهِيَ الآنَ مِنْ حَقِّكَ.","بَعْدَ عِدَّةِ أيّامٍ، ذَهَبَ جُحا إِلى جارِهِ مَرَّةً أخْرى، وَطَلَبَ مِنْهُ القِدْرَ ثانِيَةً؛ فَأعْطاهُ جارُهُ إِيّاها، وَبَعْدَ مُرورِ أسْبوعٍ، ذَهَبَ الجارُ إِلى جُحا، وَطَلَبَ مِنْهُ أنْ يُعيدَ لَهُ القِدْرَ، فَقالَ لَهُ جُحا باكِياً: إِنَّ قِدْرَكَ قَدْ ماتَتْ بِالأمْسِ! فَقالَ لَهُ جارُهُ مُتَعَجِّباً: كَيْفَ تَموتُ القِدْرُ!؟ فَقالَ جُحا: أتُصَدِّقُ أنَّ القِدْرَ تَلِدُ، وَلا تُصَدِّقُ أنَّها تَموتُ؟!"],"voc":[["قَصْعَة","وِعاءٌ كَبيرٌ يُوْضَعُ فيهِ الأكْلُ."],["أبْغِضُ","أكْرَهُ."],["الخُفّ","ما يُلْبَسُ في الرِّجْلِ مِنْ جِلْدٍ خَفيفٍ."],["إِسْكاف","صانِعُ الأحْذِيَة ِ، وَمُصْلِحُها."]],"img":[["p2-115.webp",115],["p2-116.webp",116],["p2-117.webp",117],["p2-118.webp",118]]},"grammar":{"t":"مُراجَعَةٌ","pg":119,"pts":["مراجعةٌ لعلامات الإعراب الفرعيّة، والجملتين الاسميّة والفعليّة، والمبتدأ والخبر، وأنواع الفعل، وبناء الماضي والأمر، وإعراب المضارع، والفاعل والمفعول به."],"img":[["p2-119.webp",119],["p2-120.webp",120]],"q":[]},"imla":{"t":"مُراجَعَةٌ","pg":121,"pts":["مراجعةٌ لعلامات التّرقيم والأسماء الموصولة."],"img":[["p2-121.webp",121]]},"khatt":{"t":"حرفا (ك، ف)","pg":122,"pts":["حرفا (ك، ف) بخطّ الرُّقعة."],"img":[["p2-122.webp",122]]},"taabir":{"t":"تَلْخيصُ قِصَّةٍ","pg":123,"pts":["تلخيصُ قصّة."],"img":[]}},"listen":"الطَّرائِفُ وَالنَّوادِرُ في التُّراثِ العَرَبِيِّ"}];
